COLLDATA("jamulfawaid","ur",[[9203,"سیدنا ابو درداء رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’کیا میں تمہیں خبر دوں تمہارے بہتر اعمال کی جو درجات میں زیادہ بلند کرنے والے ہوں اور تمہارے مالک کے پاس زیادہ پاکیزہ ہوں اور وہ اعمال تمہارے لیے سونا اور چاندی خرچ کرنے سے بہتر ہوں اور تمہارے لیے اس سے بھی بہتر ہوں کہ تم اپنے دشمن سے مقابلہ کرو، ان کی گردن کاٹو اور وہ تمہاری گردن ماریں۔ لوگوں نے عرض کیا: ضرور بتائیے۔ آپ نے فرمایا: وہ اللہ کو یاد کرنا ہے۔‘‘ (ترمذی)","",{"k":"ترمذی (3377)، صحیح، البانی: 2688، ابن ماجه (3790)، احمد (21195)، مؤطا (490)۔"}],[9204,"اسی سند کے ساتھ مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: تم اللہ کو کثرت سے یاد کرو حتی کہ لوگ کہیں کہ دیوانے ہیں۔ (احمد اور موصلی۔ سند کمزور)","",{"k":"احمد (27310)، موصلی وفیه دراج وقد ضعفه جماعة ووثقه غیر واحد وبقیة رجال احد اسنادی احمد ثقات، هیثمی: 16761۔"}],[9205,"معاذ بن جبل رضی اللہ عنہ نے فرمایا: ابن آدم نے کوئی ایسا عمل نہیں کیا جو اللہ کی یاد سے زیادہ اس کو اللہ کے عذاب سے نجات دینے والا ہو۔ (امام مالک)","",{"k":"مؤطا (490)، ترمذی (3377)، ابن ماجه (3790)، احمد (21195)۔","e":"ان احادیث کا مفاد یہ ہے کہ مال اور جان صرف کرنا فعلی عمل ہے، ذکر زبانی عمل ہے۔ زبانی اعمال میں سب سے زیادہ افضل عمل ذکر الہی ہے۔ ویسے بھی ہر عبادت میں ثواب نصیب اور حصہ کے مطابق نہیں ہوتا، اللہ تعالیٰ تھوڑے عمل پر زیادہ اجر دے دیتا ہے، ثواب مراتب اور شرافت کے مطابق مرتب ہوتا ہے۔ (جائزۃ الاحوذی: ۴/۴۲۴)"}],[9206,"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اگر صبح کی نماز سے سورج طلوع ہونے تک میں اس قوم کے ساتھ بیٹھوں جو اللہ کو یاد کرتی ہیں تو یہ عمل مجھے زیادہ پسند ہے اولاد اسماعیل سے چار گردنیں آزاد کرنے سے۔ اور اگر میں اس قوم کے ساتھ بیٹھوں جو نماز عصر سے سورج غروب ہونے تک اللہ کی یاد کرتے ہوں وہ مجھے چار غلام آزاد کرنے سے زیادہ پسند ہے۔ (ابو داؤد)","",{"k":"ابوداؤد (3667)، حسن، البانی: 3114۔","e":"ثابت ہوا کہ ذکر الہی یعنی قرآن کی تلاوت، تسبیح و تہلیل، درود علم، تفسیر وحدیث اور دیگر علوم شریعت صدقہ کرنے اور غلام آزاد کرنے سے افضل ہے۔ (عون المعبود: ۳/۳۶۳)"}],[9207,"سیدنا نعمان بن بشیر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: دعا ہی عبادت ہے۔ پھر آپ صلی اللہ علیہ وسلم نے یہ آیت تلاوت کی: ’’تمہارے رب نے فرمایا ہے: مجھے پکارو میں تمہاری دعا قبول کروں گا۔ بے شک وہ لوگ جو تکبر کرتے ہیں میری عبادت سے وہ جہنم میں عنقریب داخل ہوں گے ذلیل ہونے والے۔‘‘ (ترمذی)","",{"k":"ترمذی (3372)، صحیح، البانی: 2590، ابن ماجه (3828)۔"}],[9208,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: کوئی عبادت اللہ کے ہاں دعا سے بڑھ کر باعث اکرام نہیں ہے۔","",{"k":"ترمذی (3370)، حسن، البانی: 2684، ابن ماجه (3829)۔"}],[9209,"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’دعا عبادت کا مغز ہے۔‘‘","",{"k":"ترمذی (3371)، ضعیف، البانی: بهذا اللفظ: 669۔"}],[9210,"سیدنا ابن عمر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس کے لیے دعا کا دروازہ کھولا جائے اس کے لیے رحمت کے دروازے کھول دیے جاتے ہیں اور اللہ تعالیٰ سے کوئی چیز نہیں مانگی گئی جو عافیت مانگنے سے اللہ کے نزدیک زیادہ پسند ہو۔ اور دعا نفع دیتی ہے اس چیز کے بارے میں جو نازل ہو چکی ہو اور اس چیز کے بارے میں جو نازل نہیں ہوئی اور تقدیر کو رد نہیں کرتی مگر دعا۔ پس تم دعائیں مانگنا اپنے اوپر لازم کرلو۔‘‘","",{"k":"ترمذی (3548)، ضعیف، البانی: 708۔"}],[9211,"سیدنا جابر رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا کہ آپ نے فرمایا: ’’جب کوئی بندہ دعا کرتا ہے تو اللہ تعالیٰ اس کو وہ چیز دیتا ہے جو اس نے مانگی ہو یا اللہ تعالیٰ اس سے اس کے برابر کوئی بدی دور کر دیتا ہے۔ جب تک وہ گناہ یا قطع رحمی کی دعا نہ کرے۔‘‘ (یہ ترمذی کی مرویات ہیں)","",{"k":"ترمذی (3381)، حسن، البانی: 2692، احمد (14465)۔"}],[9212,"اور اس روایت میں رزین کے الفاظ یہ ہیں: مگر اللہ تعالیٰ اس کو وہ چیز دے دیتا ہے یا اس کے لیے آخرت کا ذخیرہ بنا دیتا ہے جو دنیاوی چیز سے بہتر ہے یا اس سے بدی روک دیتا ہے......تا آخر۔","",{"k":"رزین۔"}],[9213,"سیدنا جابر رضی اللہ عنہ سے روایت ہے، وہ مرفوع بیان کرتے ہیں: کیا میں تمہیں وہ چیز نہ بتا دوں جو تمہیں تمہارے دشمن سے نجات دے دے اور تمہارا رزق تمہارے لیے لے آئے؟ وہ یہ ہے کہ تم اللہ تعالیٰ سے رات دن دعا میں مانگو۔ بے شک دعا مومن کا اسلحہ ہے۔ (الموصلی۔ سند ضعیف)","",{"k":"موصلی: 1812۔ وفیہ محمد بن ابی حمید وھو ضعیف، ہیثمی: 17199۔","e":"دعا میں اظہار فقر و احتیاج ہوتا ہے، عجز و نیاز ہوتا ہے، تدلل و پستی ہوتی ہے اور اللہ کی قدرت و قوت کا اعتراف ہوتا ہے، اس لیے یہ اللہ کے نزدیک ہر چیز سے مکرم و محترم ہے، اللہ کا فرمان ہے: ﴿إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ﴾ (الحجرات: ۱۳) ’’اللہ کے نزدیک تمہارا زیادہ عزت والا وہ ہے جو زیادہ تقویٰ والا ہے۔‘‘ یہ آیت مبارکہ اور اس حدیث میں تعارض نہیں، آیت میں ہر چیز میں تقویٰ کو عزت کا باعث قرار دیا گیا ہے اور حدیث میں اذکار و عبادات میں دعا کو عزت کا باعث قرار دیا گیا ہے۔ (جائزۃ الاحوذی: ۴/۳۲۱) ۲۔ دعا عبادت کا لب لباب اور خلاصہ ہے، وجہ یہ ہے کہ داعی جب اللہ سے دعا کرتا ہے تو وہ اس کے سوا ہر ایک سے آرزو منقطع کر دیتا ہے، یہی توحید کی حقیقت ہے۔ جس طرح حج میں عرفات میں ٹھہرنا ہے، یہ چونکہ اہم ترین حج کا رکن ہے اسی طرح دعا عبادت کا اہم رکن ہے اس پر آیت سے استدلال کیا گیا ہے کہ دعا کو عبادت قرار دیا گیا ہے اور اس سے اعراض کرنے والے کو ذلیل قرار دیا گیا ہے جو تکبر کی وجہ سے دعا سے اعراض کرتا ہے وہ کفر کرتا ہے۔ (جائزۃ الاحوذی: ۴/۳۲) ۳۔ یہ بھی ثابت ہوا کہ دعا رائیگاں نہیں جاتی، اگر تقدیر کے موافق ہو تو قبول ہو جاتی ہے، جو یہ اللہ سے مانگتا ہے وہ اسے عطا کر دیتا ہے یا پھر اس دعا کی وجہ سے اس سے بلا دور کر دی جاتی ہے یا پھر آخرت میں ذخیرہ ہو جاتی ہے بشرطیکہ قطع رحمی اور گناہ کی دعا نہ ہو، یہ قبول نہیں ہوتی۔ (جائزۃ الاحوذی: ۴/۳۲۴)\nاور جسے دعا کے آداب اور شرائط کا علم ہو اور پھر اسے دعا کی کثرت سے کرنے کی توفیق بھی نصیب ہو تو دعا کا نفع ضرور پائے گا۔ (ص ۵۱۵)"}],[9214,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ہمارا رب ہر رات آسمان دنیا پر اترتا ہے جب رات کا آخری تیسرا حصہ رہ جاتا ہے تو فرماتا ہے: کوئی مجھے پکارتا ہے میں اس کی دعا قبول کروں، کوئی مجھ سے مانگتا ہے کہ میں اسے دے دوں۔ کون مجھ سے بخشش مانگتا ہے کہ میں اس کو بخش دوں۔‘‘","",{"k":"بخاری (1145)۔ مسلم (758)۔ ابوداؤد (4733)۔ ترمذی (3498)۔ ابن ماجہ (1366)۔ دارمی (1479)۔ احمد (10377)۔ مؤطا (496)۔"}],[9215,"اور ایک روایت میں ہے: اللہ تعالیٰ مہلت دیتا ہے یہاں تک کہ رات کا تیسرا حصہ گزر جائے تو آسمان دنیا پر اترتا ہے اور کہتا ہے کہ ہے کوئی بخشش مانگنے والا، کیا ہے کوئی توبہ کرنے والا، کیا ہے کوئی مانگنے والا، کیا ہے کوئی پکارنے والا۔ یہاں تک کہ فجر ہو جاتی ہے۔","",{"k":"مسلم (758)۔"}],[9216,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب رات کا نصف حصہ گزر جاتا ہے یا اس کے دو ثلث گزر جاتے ہیں تو اللہ تعالیٰ اترتا ہے...... مثل اس کے۔","",{"k":"مسلم (758)۔"}],[9217,"سیدنا ابوامامہ باہلی رضی اللہ عنہ بیان کرتے ہیں کہ عرض کیا گیا: یا رسول اللہ! کون سی دعا زیادہ قبول ہوتی ہے؟ آپ نے فرمایا: رات کے آخری حصے کے درمیان میں۔ اور فرض نمازوں کے بعد۔ (ترمذی)","",{"k":"ترمذی (3499)۔ بخاری (7494)۔ ابوداؤد (4733)۔ ترمذی (3498)۔ ابن ماجہ (1366)۔ دارمی (1484)۔ احمد (11482)۔ مؤطا (496)۔ حسن البانی: 2782۔","e":"اللہ تعالیٰ کے آسمان دنیا کی طرف نزول کے بارے میں اختلاف ہے، ایک قول ہے کہ عرش خالی کیے حقیقت میں اترتے ہیں یہ قول تو بالکل غلط ہے، ایک گروہ ان احادیث کا منکر ہے وہ اللہ کے اترنے کو مانتا ہی نہیں۔ یہ حقائق کا خون کرنا ہے اور جہالت و عناد ہے، ایک قول ہے کہ جس طرح احادیث میں آیا ہے اسی طرح ہے کہ اللہ تعالیٰ اترتے ہیں کیفیت نامعلوم ہے۔ ایک قول ہے اللہ کی ذات نہیں اترتی اس کے افعال اترتے ہیں۔ یعنی اترنے سے مراد ہے جو وہ حکم دیتا ہے اور منع کرتا ہے اور دعا کرنے والوں پر خاص مہربانی کرتا ہے۔ حافظ ابن حجر رحمہ اللہ اس تاویل کی جانب مائل ہیں اور اس کے قائل ہیں۔ امام بیضاوی رحمہ اللہ کے نزدیک اترنے سے اس کا نور رحمت مراد ہے۔ اس سے مراد ہے کہ اللہ تعالیٰ صفت جلال سے، جو اس کے غضب و انتقام پر دلالت کرتی ہے، صفت اکرام کی طرف منتقل ہوتے ہیں جو کہ رحمت اور نرمی کا تقاضا کرتی ہے، اس کی طرف اترتے ہیں۔ لیکن ان تمام تاویلات کی تردید کرتے ہوئے اور اترنے کی کیفیت نامعلوم ہونے کی تائید میں علامہ ابن باز رحمہ اللہ اپنی وضاحت میں فرماتے ہیں، صحابہ کرام رضی اللہ عنہم اور ان کے ہمقدم اہل سنت اللہ کے علو و بلندی کی جہت ثابت کرتے ہیں اور یہ فرماتے ہیں کہ یہ سب بزرگان دین اس بات پر ایمان رکھتے تھے کہ اللہ سبحانہ عرش کے اوپر ہے، اس کی مثال اور کیفیت معلوم نہیں جس طرح اللہ تعالیٰ کی ذات گرامی کے لائق ہے، اسی طرح اترتے ہیں ہمیں کتاب و سنت کے ان دلائل پر ایمان لانا چاہیے، کسی قسم کی تاویل درست نہیں۔ یہی طریقہ صحیح اور محفوظ ہے۔ اب رہی بات اترنے کا وقت مختلف بتایا گیا ہے رات کا نصف یا تہائی حصہ تو پریشان ہونے کی ضرورت نہیں، احوال و زمان اور مقام کے لحاظ سے چونکہ رات کے یہ اوقات مختلف ہوتے رہتے ہیں اس لیے اوقات شب مختلف بیان کیے۔ یا جس طرح نبی اکرم صلی اللہ علیہ وسلم کو بذریعہ وحی پتہ چلتا رہا آپ اسے اسی طرح بتاتے رہے اور آگے صحابہ کرام رضی اللہ عنہم نے بھی اسی طرح بیان کیا۔ اس میں تین باتیں بیان ہوئی ہیں۔ انسان مضرت اور نقصان دور کرنا چاہتا ہے یہ استغفار سے ہوتا ہے یا مسرت اور فوائد حاصل کرنا چاہتا ہے یہ اللہ سے سوال کرنے سے حاصل ہوتا ہے یہ نقصان دور کرنا اور فائدہ حاصل کرنا یا تو دنیاوی ہے یا دینی ہے۔ یہ دعا سے حاصل ہوتا ہے۔ شفا طلب کرنے والے اور مشکل حل کرانے والے کو اور رزق طلب کرنے والے کا بھی ذکر آتا ہے کہ اللہ اسے پکارتے ہیں یہ بھی ان بنیادی تینوں امور میں شامل ہیں جو حدیث میں مذکور ہیں۔ نمازوں کے بعد اور رات کی اس گھڑی میں سوال کی ترغیب کی وجہ یہی ہے کہ یہ قبولیت کے اوقات ہیں اور اطاعت کے بعد ثواب بڑھتا ہے، اس لیے ان اوقات میں وہ کائنات کا جواد و کریم بلا بلا کر نوازشات کی ترغیب دے رہا ہے۔ تو ان میں رات کے آخر میں نماز کو پہلے حصے کی بہ نسبت افضل قرار دیا گیا ہے اور جو بیدار ہونے پر اعتماد رکھتا ہے اس کے لیے وتر کو رات کے اس حصہ تک مؤخر کرنے کی فضیلت ہے اور رات کے وقت دعا و استغفار افضل ہے اور قبول ہوتی ہے۔ ایک بات یاد رہے کہ بعض اوقات دعا قبول نہیں ہوتی۔ اس میں کئی وجوہ ہو سکتی ہیں۔ دعا کرنے والے کا کھانا پینا اور لباس حرام ہو۔ یا دعا والا جلدی قبول کروانا چاہتا ہے مگر یہ دعا قطع رحمی کی ہو یا گناہ کی ہو اسے اللہ قبول نہیں کرتے یا یہ ہوتا ہے کہ دعا قبول ہو جاتی ہے بندے کی مصلحت کے لیے اس میں تاخیر کر دی جاتی ہے، لہذا دعا کرتے جائیں قبولیت نہ پانے کی شرائط کا خیال رکھتے جائیں بہر صورت دعا ضائع نہیں جاتی۔ (فتح الباری: ۳/۳۰) یہ حدیث ان آیات کی تشریح ہے: ﴿كَانُوا قَلِيلًا مِّنَ اللَّيْلِ مَا يَهْجَعُونَ﴾ یہ رات کو کم سوتے تھے اور ارشاد گرامی ہے: ﴿وَبِالْأَسْحَارِ هُمْ يَسْتَغْفِرُونَ﴾ (الذاریات: ۱۷) سحری کے وقت یہ استغفار کرتے ہیں۔"}],[9218,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اذان اور اقامت کے درمیان کی دعا رد نہیں ہوتی۔ (ابوداؤد اور ترمذی)","",{"k":"ابوداؤد (521)۔ صحیح، البانی: 489۔ ترمذی (212)۔ احمد (12256)۔"}],[9219,"سیدنا سہل بن سعد رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’دو دعائیں رد نہیں ہوتیں یا فرمایا کم ہی رد ہوتی ہیں۔ اذان کے وقت کی دعا اور جنگ کے وقت کی دعا، جب بعض بعض کا گوشت کاٹ رہے ہوں۔‘‘","",{"k":"ابوداؤد (2540)۔ صحیح، البانی: 2215۔ دون ووقت المطر، دارمی (1200)۔"}],[9220,"اور دوسری روایت میں ہے: بارش کے نیچے کی دعا۔ (ابوداؤد)"],[9221,"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: بندہ اپنے رب کے زیادہ قریب سجدے کی حالت میں ہوتا ہے تو دعا زیادہ کیا کرو۔ (مسلم، ابوداؤد اور نسائی)","",{"k":"مسلم (482)۔ ابوداؤد (875)۔ نسائی (1137)۔ احمد (9165)۔"}],[9222,"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس کو یہ پسند ہو کہ اللہ تعالیٰ مصیبت اور تکلیف میں اس کی دعا قبول کرے تو وہ آرام اور فرصت کے وقت میں کثرت سے دعا کیا کرے۔‘‘ (ترمذی)","",{"k":"ترمذی (3382)۔ حسن، البانی: 2693۔"}],[9223,"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: مظلوم کی دعا قبول ہوتی ہے خواہ وہ بدکار ہو، پس بدی کا اثر اس کے بدن پر ہے۔ (احمد، بزار)","",{"k":"احمد (8577)۔ ہیثمی: 17227۔ بزار بنحوہ واسنادہ حسن۔"}],[9224,"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: تین اشخاص کی دعا رد نہیں ہوتی: روزہ دار کی افطار کے وقت، عادل حکمران کی اور مظلوم کی دعا۔ اللہ ان کی دعاؤں کو بادلوں سے بلند کر دیتا ہے، آسمان کے دروازے کھول دیتا ہے اور رب تعالیٰ فرماتا ہے: میں تیری ضرور مدد کروں گا، خواہ کچھ وقت کے بعد سہی۔","",{"k":"ترمذی (3598)۔ ضعیف، البانی: 727۔ لکن صح منہ شطر الاول بلفظ المسافر مکان الامام العادل وفی روایۃ الوالد۔"}],[9225,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تین دعائیں قبول ہوتی ہیں، ان کے قبول ہونے میں کوئی شک نہیں ہے۔ مظلوم کی دعا، مسافر کی دعا، باپ کی بیٹے کے خلاف دعا۔‘‘","",{"k":"ترمذی (1905)۔ حسن، البانی: 1555۔ ابن ماجہ (3862)۔"}],[9226,"سیدنا عبداللہ بن عمرو بن العاص رضی اللہ عنہ سے روایت ہے کہ وہ کہتے ہیں کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’کوئی دعا اتنی جلدی قبول نہیں ہوتی جس قدر کہ غائب کی دعا غائب کے لیے ہوتی ہے۔‘‘","",{"k":"ترمذی (1980)۔ ضعیف، البانی: 338۔ ابوداؤد (1535)۔"}],[9227,"سیدہ ام درداء رضی اللہ عنہا سے مروی ہے کہ مجھے میرے سردار ابودرداء رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب ایک مرد اپنے بھائی کے لیے پس پشت دعا کرتا ہے تو فرشتے کہتے ہیں: آمین اور تیرے لیے اس کی مثل ہے۔ (مسلم اور ابوداؤد)","",{"k":"مسلم (2732)۔ ابوداؤد (1534)۔ ابن ماجہ (2895)۔ احمد (21200)۔","e":"اذان اور اقامت کے درمیان شرف وفضل والا وقت ہوتا ہے، اس میں دعا قبول ہوتی ہے چونکہ اذان اللہ کی کبریائی کا اعلان ہے۔ اس وقت کو غنیمت جان کر اللہ تعالیٰ سے مانگا جائے۔ ہوسکتا ہے تمام مشکلات دور ہو جائیں۔ اور اس وقت انسان نماز کے انتظار میں ہوتا ہے اور نماز کے انتظار والا نماز ہی میں تصور ہوتا ہے اور نماز قبولیت دعا کا محل ہے۔ بندہ اس وقت اپنے رب کی بارگاہ میں راز و نیاز میں مصروف ہوتا ہے اس لیے اس کی دعا رد نہیں ہوتی۔ (تفہیم الاسلام: ۲/۹۷۹) جنگ میں چونکہ موت سامنے ہوتی ہے، اس لمحہ بہت زیادہ اخلاص ہوتا ہے اور بارش چونکہ رحمت ہوتی ہے۔ اس مناسبت سے دعا جلدی قبول ہوتی ہے۔ (عون المعبود: ۲/۳۲۷) سجدے کی حالت میں دعا کی ترغیب اس لیے دی گئی ہے کہ بندہ اس شہنشاہ کبریا کے سامنے حالت سجدہ میں نہایت ہی تذلل کا اظہار کرتا ہے اور اپنی بندگی کا اظہار کرتا ہے اور رب کی ربوبیت کا اعتراف کرتا ہے، یہ قبولیت کا مقام ہے۔ اس لیے سجدہ میں کثرت سے دعا کی ترغیب ہے۔ (عون المعبود: ۱/۳۲۶) ایک مسلمان تیر چلانے سے پہلے ہی اس کو تیار رکھتا ہے یعنی حالت فراغت انسان کو اپنے اللہ سے دور کر دیتی ہے اور غفلت کا شکار کر دیتی ہے لہذا حالت صحت و فراغت میں اللہ کے سامنے جھکنا اور حالت اضطرار سے پہلے اس سے پناہ میں آنا ہی مومنانہ فراست ہے اس لیے وہ بادشاہ حقیقی بھی اپنے بندے کا خیال رکھتا ہے اور اس کی پریشانی کے وقت اس کی التجاء سنتا ہے۔ (جائزۃ الاحوذی: ۴/۴۲۷) غائب کی دعا غائب کے لیے اس لیے جلدی قبول ہوتی ہے کہ اس میں خلوص ہوتا ہے، صدق نیت ہوتا ہے اور یہ دعا ریا کاری اور شہرت سے خالی ہوتی ہے۔ (جائزۃ الاحوذی: ۳/۳۱۵) مسافر، مظلوم، اور والد کی دعا کو مقبول قرار دیا گیا ہے، وجہ یہ ہے کہ قبولیت کا باعث اس میں مکمل طور پر پایا جاتا ہے کیونکہ یہ دعائیں سب سے کٹ کر اللہ کی طرف رجوع کی حالت میں ہوتی ہیں۔ ان میں قلبی رقت ہوتی ہے۔ دلی انکساری ہوتی ہے اور حالت پراگندہ ہوتی ہے، مسافر وطن مالوف سے جدا ہوتا ہے اور مانوس اشیا سے علیحدہ ہو رہا ہوتا ہے اور سفر کے حادثات سے اچانک دو چار ہونے سے خوفزدہ ہوتا ہے۔ اس وجہ سے اس کا رجوع اللہ کی طرف ہوتا ہے اور رقت طاری ہوتی ہے۔ مظلوم حالت اضطراری کی وجہ سے رب کی طرف پلٹتا ہے، یہ اس کی دعا کی قبولیت کی وجہ ہے، والد کو اولاد سے مہربانی ہوتی ہے، اسے اولاد جان سے بھی زیادہ عزیز ہوتی ہے اس لیے وہ اپنی پوری تندہی سے دعا کرتا ہے۔ (انجاز الحاجہ: ۱/۱۸۱)"}],[9228,"سیدنا ابن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: چیچک کو نہ چھپاؤ اور جو شخص دوسرے کی تحریر دیکھتا ہے وہ آگ میں دیکھتا ہے۔ اللہ تعالیٰ سے سیدھی ہتھیلی کے ساتھ سوال کرو اور ہاتھ کی پشت کی طرف سے سوال نہ کرو۔ اور جب دعا سے فارغ ہوتے ہو تو دونوں ہاتھوں کو چہرے پر مل لو۔ (ابوداؤد نے ضعیف کہا ہے)","",{"k":"ابوداؤد (1485)، ضعیف، البانی: 318، ابن ماجہ (1181)۔"}],[9229,"سیدنا ابن عباس رضی اللہ عنہما سے ایک روایت میں ہے فرمایا: سوال یہ ہے کہ تو دونوں ہاتھ اپنے شانے تک اٹھائے یا اس کے مانند اور استغفار یہ ہے کہ تو ایک انگلی کے ساتھ اشارہ کرے اور گڑگڑانا یہ ہے کہ دونوں ہاتھ ملا کر پھیلائے اور ہاتھوں کو بلند کرے اور ان کی پشت کو اپنے چہرے کی طرف رکھے۔","",{"k":"ابوداؤد (1489)، صحیح، البانی: 1322۔"}],[9230,"سیدنا انس بن مالک رضی اللہ عنہ سے مروی ہے کہ میں نے نبی کریم صلی اللہ علیہ وسلم کو دعا کرتے دیکھا، دو ہتھیلیوں کے اندرونی حصے کے ساتھ بھی اور ان دونوں کے ظاہر کے ساتھ بھی۔ (ابوداؤد)","",{"k":"ابوداؤد (1487)، صحیح، البانی: 1319۔ مسلم (895)، بلفظہ جعل ظاہر کفیہ مما یلی وجہہ۔"}],[9231,"سیدنا خلاد بن سائب انصاری رضی اللہ عنہ روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم جب اللہ سے سوال کرتے تھے تو اپنی دونوں ہتھیلیوں کے اندرونی حصے کو اپنی طرف رکھتے تھے اور جب پناہ مانگتے تھے تو ہاتھوں کے ظاہر کو اپنی طرف رکھتے تھے۔ (احمد کی مرسل روایت ہے)","",{"k":"احمد (16129)، بإرسال واسنادہ حسن، ہیثمی: 17333۔","e":"ان احادیث سے معلوم ہوا کہ دعا مانگنے کے بعد اپنے دونوں ہاتھوں کو اپنے چہرے پر ملنا چاہیے۔ اس کی وجہ یہ ہے کہ دعا کے وقت اللہ تعالیٰ کی جناب میں اٹھے ہوئے ہاتھ، رحمت الہی سے لبریز ہو جاتے ہیں تو اس کی رحمت کو شکریہ کے ساتھ چہرے پر مل لیا جاتا ہے چونکہ چہرہ اعضائے جسم میں سے سب سے زیادہ اشرف عضو ہے، اس پر ہاتھ ملنے سے تمام اعضاء کی نمائندگی ہو جاتی ہے اور وہ تمام اس رحمت میں شامل ہو جاتے ہیں۔ اسے ضعیف قرار دینے والے زمانے کے محدث ہیں تاہم حسن لغیرہ قرار دینے والے بھی کم نہیں۔ ابن حجر، امام اسحاق، امام نووی، امام مناوی، امام صنعانی اور امام شوکانی رحمہم اللہ نے انہیں قوی اور حسن قرار دیا ہے۔ (تفہیم الاسلام: ۲/۹۸۱)"}],[9232,"سیدنا ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ایک آدمی دو انگلیوں کے ساتھ دعا کرتا تھا۔ پس آپ صلی اللہ علیہ وسلم نے فرمایا: ایک سے ایک سے۔ ترمذی نے کہا: اس کا معنی ہے کہ وہ انگلیوں سے اشارہ کرتا تھا، جب شہادت کے وقت دعا کرتا تھا اور اس وقت ایک انگلی کے ساتھ ہی اشارہ جائز ہے۔","",{"k":"ترمذی (3557)، حسن، صحیح: 2820، نسائی (1272)، احمد (9152)۔","e":"یہ انگلی کا تشہد میں اشارہ بھی مراد ہو سکتا ہے۔ یہ زیادہ قرین قیاس ہے یا پھر عام دعا میں بھی اشارہ ہو سکتا ہے، ایک انگلی سے اشارے کی وجہ یہ ہے کہ جس سے دعا کی جارہی ہے وہ واحد ہے، اس لیے دو سے نہیں ایک ہی انگلی سے اشارہ کیا جائے۔ وہ بھی سبابہ انگلی سے کیا جائے۔ (جائزۃ الاحوذی: ۴/۵۱۹)"}],[9233,"سیدنا عبداللہ ابن عمرو بن العاص رضی اللہ عنہما بیان کرتے ہیں کہ میں نے نبی کریم صلی اللہ علیہ وسلم کو دائیں ہاتھ پر تسبیحات شمار کرتے دیکھا ہے۔ (ترمذی، نسائی، ابوداؤد بلفظہ)","",{"k":"ابوداؤد (1502)، صحیح، البانی: 1330، ترمذی (3486)، نسائی (1355)۔","e":"ثابت ہوا کہ دائیں ہاتھ کے پوروں پر تسبیحات پڑھی جائیں، وجہ یہ ہے کہ یہ زیادہ مقدم ہے۔ اگر بائیں سے بھی تسبیحات کر لیں تو اجازت ہے مگر دایاں ہاتھ اولیٰ ہے اور تسبیح سے بھی پوروں پر پڑھنا زیادہ اولیٰ ہے تاہم تسبیح پر پڑھنا بدعت نہیں۔ یہ پورے چونکہ گواہی دیں گے اس لیے ان پر تسبیحات پڑھنا مستحب ہے۔ (عون المعبود: ۱/۵۵۲)"}],[9234,"سیدنا سلمان فارسی رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: تمہارا رب زندہ، کریم ہے وہ اپنے بندے سے حیا کرتا ہے جب بندہ اس کی طرف دونوں ہاتھ اٹھا کر دعا کرتا ہے تو ان کو خالی اور ناکام واپس نہیں کرتا ہے۔ (ابوداؤد و ترمذی بلفظہ)","",{"k":"ترمذی (3556)، صحیح، البانی: 2819، ابوداؤد (1488)، ابن ماجہ (3865)، احمد (23202)۔","e":"حیا والا ہونا اور کریم ہونا اللہ کے لیے یہ دونوں صفات بغیر تاویل کے ثابت ہیں، اس سے ثابت ہوا دعا میں ہاتھ اٹھانا جائز ہے، وجہ یہ ہے کہ دوران دعا ہاتھ اٹھانے میں محتاجی، فاقہ مستی کا ایک انتہائی عاجزانہ اظہار ہے کہ اے غنی کائنات! اے جلالت و عظمت کے پیکر! اے دو جہانوں کے کریم! میں نے مسکینی کا پیالہ تیرے سامنے رکھ دیا ہے، اب میری حاجت برآری کرنا، اسے خالی نہ لوٹانا، یہی وجہ ہے کہ اس کا جود و کرم اور اس کی مہربانی جوش مارتے ہیں، سمندر کی موجیں بن جاتے ہیں اور وہ قادر مطلق جس کے سامنے کوئی دم نہیں مارسکتا، وہ اپنی شان کریمی کے خلاف تصور کرتا ہے کہ اپنے اس مسکین بندے کو اپنے در رحمت سے خالی لوٹائے۔ ایک روایت میں آتا ہے کہ نبی اکرم صلی اللہ علیہ وسلم نہ صرف نماز استسقاء میں ہاتھ اٹھاتے تھے اور کسی چیز میں نہیں اٹھاتے تھے۔ (فقہ الاسلام: ۱۰/۳۳۷) اس کا حل یہ ہے کہ اس میں ہاتھ اٹھانے کی نفی نہیں بلکہ یہ بتایا گیا ہے کہ اتنے مبالغے سے اور کسی چیز میں اتنے ہاتھ نہیں اٹھاتے تھے جتنے نماز استسقاء میں اٹھاتے تھے تو مبالغہ آمیز اٹھانے کی نفی ہے، ہاتھ اٹھانے کی نہیں۔ (تحفۃ الاحوذی: ۱/۲۴۶، تفہیم الاسلام: ۲/۹۷۹)"}],[9235,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اکرم صلی اللہ علیہ وسلم نے فرمایا: تم اللہ تعالیٰ سے اس یقین کے ساتھ دعا مانگو کہ دعا قبول ہوگی اور یہ جان لو کہ اللہ تعالیٰ غافل دل سے دعا قبول نہیں کرتا ہے۔ (ترمذی)","",{"k":"ترمذی (3479)، حسن، البانی: 2766۔","e":"دعا کی صورت میں غفلت ہو تو اللہ اسے قبول نہیں کرتا۔ اس حالت میں نیکی کریں، برائی سے اجتناب کریں اور حضور قلب ہو، اور قبولیت کے اوقات میں ہو، جیسا کہ عرفات کا دن ہے اور حالت قبولیت بھی مدنظر ہو۔ مثلاً سجدہ کی حالت ہو اور یہ اعتقاد ہو کہ اللہ کا وسیع کرم ہے وہ میری دعا کو ناکام نہ کرے گا۔ (جائزۃ الاحوذی: ۴/۴۷۷)"}],[9236,"سیدنا فضالہ بن عبید رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے ایک مرد کو سنا جو اپنی نماز میں دعا مانگ رہا تھا اور اس نے نبی صلی اللہ علیہ وسلم پر درود نہیں بھیجا تھا۔ آپ نے فرمایا: ’’اس نے جلدی کی ہے۔ پھر اس کو بلا کر فرمایا یا کسی دوسرے کو فرمایا: جب تم میں سے کوئی آدمی نماز پڑھے تو وہ اللہ تعالیٰ کی حمد وثنا کہے، پھر نبی صلی اللہ علیہ وسلم پر درود پڑھے اور پھر جو چاہے دعا مانگے۔‘‘ (ترمذی، ابوداؤد، نسائی)","",{"k":"ترمذی (3477)، صحیح، البانی: 2767، نسائی (1284)۔"}],[9237,"سیدنا عمر بن خطاب رضی اللہ عنہ بیان کرتے ہیں کہ دعا آسمان وزمین کے درمیان کھڑی کی جاتی ہے اور اوپر نہیں جاتی یہاں تک کہ اپنے نبی صلی اللہ علیہ وسلم پر درود پڑھا جائے رزین نے اضافہ کیا ہے اور تم مجھے پیچھے رہنے والے سوار کی مثل نہ بناؤ بلکہ دعا کے شروع میں، وسط میں اس کے اختتام پر درود پڑھا کرو۔ (ترمذی الفاظ رزین کے ہیں)","",{"k":"ترمذی (476)، حسن، البانی: 403۔","e":"ثابت ہوا کہ نبی صلی اللہ علیہ وسلم پر درود پڑھنا دعا کی قبولیت کا باعث ہے۔ (تحفۃ الاحوذی: ۱/۳۵۴)"}],[9238,"سیدنا ابوزہیر نمیری رضی اللہ عنہ سے روایت ہے کہ ایک رات رسول اللہ صلی اللہ علیہ وسلم کی معیت میں ہم لوگ باہر گئے تو ایک آدمی کے پاس سے گزرے جو بڑی عاجزی کے ساتھ دعا میں مصروف تھا۔ آپ صلی اللہ علیہ وسلم اس کی دعا سننے کے لیے کھڑے ہو گئے اور فرمایا: ’’قبولیت واجب ہوگئی اس نے خاتمہ بھی کیا۔‘‘ لوگوں میں سے ایک نے عرض کی: یارسول اللہ! وہ کس چیز سے ختم کرے گا تو قبول ہوگی؟ آپ نے فرمایا: آمین کے ساتھ۔ پس اگر آمین کے ساتھ دعا ختم کی تو دعا قبول ہوگئی۔ تو وہ مرد جس نے آپ صلی اللہ علیہ وسلم سے سوال کیا تھا لوٹ کر دعا کرنے والے کے پاس گیا اور اس کو کہا فلاں اپنی دعا آمین کے ساتھ ختم کر اور تجھے بشارت ہے۔ (ابوداؤد)","",{"k":"ابوداؤد (938)، ضعیف، البانی: 199۔","e":"بہر صورت دعا کے بعد یا اس کے ساتھ آمین کہنا صحیح احادیث سے ثابت ہے، اگر چہ یہ حدیث ضعیف ہے۔ (عون المعبود: ۱/۳۵۳)"}],[9239,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کوئی دعا کرے تو یہ نہ کہے کہ یا اللہ اگر تو چاہے تو بخش دے، اگر تو چاہے تو میرے اوپر رحمت نازل فرما بلکہ پختہ عزم کر کے سوال کرے کیونکہ اللہ پر جبر کرنے والا تو کوئی نہیں ہے۔‘‘","",{"k":"بخاری (6339)، مسلم (2679)، ابوداؤد (1483)، ترمذی (3497)، احمد (10116)، مؤطا (494)۔","e":"ہر کام اللہ کی مشیت ہی سے ہوتا ہے لیکن دعا میں یہ کہنے سے کہ اگر تیری مرضی ہے تو مجھے دے۔ سائل کی لا پروائی پائی جاتی ہے، اس لیے ایسے الفاظ سے منع کیا گیا ہے۔ اس میں یہ بھی قباحت ہے کہ اس سے ایسا تاثر پیدا ہوتا ہے کہ اللہ کو مجبور بھی کیا جا سکتا ہے، اس لیے حکم ہے کہ دعا پوری الحا وزاری اور جدو جہد سے کی جائے اور اپنا مطلوب پختہ انداز میں اس کی بارگاہ میں پیش کرنا چاہیے اور بڑی سے بڑی چیز بھی اس کے ہاں معمولی ہے، وہ سب کچھ دے سکتا ہے اس لیے گڑ گڑا کر پورے اعتماد کے ساتھ دعا کی جائے۔ اس سے ثابت ہوا کہ قبولیت کی پختہ امید رکھ کر اللہ سے دعا کی جائے اور اس کریم سے مایوس نہ ہوا جائے بلکہ اس کی رحمت سے امید رکھی جائے اور ایک تنگدست کی سی مانند اس سے التجا کی جائے۔ (فتح الباری: ۱۱/۱۴۰)"}],[9240,"ابو نعامہ سے مروی ہے کہ اس نے سعد رضی اللہ عنہ کے بیٹے سے روایت کی ہے کہ میرے باپ نے مجھے دعا میں اس طرح کہتے ہوئے سنا: اے اللہ! میں تجھ سے جنت کا اور اس کی نعمتوں اور اس کی تازگی کا اور فلاں چیز کا اور فلاں چیز کا سوال کرتا ہوں۔ اور میں آگ سے تیری پناہ طلب کرتا ہوں، اس کی زنجیروں سے، اس کے طوق سے اور فلاں عذاب اور فلاں عذاب سے۔ تو میرے باپ نے مجھے کہا: اے بیٹا! میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے، آپ نے فرمایا: ’’عنقریب ایک قوم آئے گی جو دعا میں حد سے تجاوز کریں گے۔ بیٹا! تو ان میں نہ بن۔ اگر تجھے جنت دی گئی تو اس میں جو بھلائی موجود ہے وہ تجھے دی جائے گی اور اگر تجھے آگ سے پناہ دی گئی تو تجھے اس سے بھی پناہ دی جائے گی۔ اور جو کچھ اس میں شر موجود ہے اس سے بھی پناہ دی جائے گی۔ (سنن ابو داؤد)‘‘","",{"k":"ابوداؤد (1480)، حسن، صحیح، البانی: 1313، احمد (1486)۔","e":"اس میں تلقین ہے کہ جامع دعائیں کی جائیں، دعاؤں میں مبالغہ آرائی سے اجتناب کیا جائے اور حد سے تجاوز نہ کیا جائے۔ (عون المعبود: ۱/۵۵۱)"}],[9241,"سیدنا معاذ بن جبل رضی اللہ عنہ سے روایت ہے، وہ کہتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے ایک آدمی کو کہتے سنا: یا ذا الجلال والا کرام تو فرمایا: ’’تیری دعا قبول کی گئی ہے اب تو سوال کر‘‘ آپ صلی اللہ علیہ وسلم نے ایک مرد کو دعا کرتے سنا کہ یا اللہ میں تجھ سے صبر کا سوال کرتا ہے تو فرمایا: ’’تو نے اللہ سے بلا مانگی ہے، پس تو اللہ تعالیٰ سے عافیت طلب کر۔‘‘ (ترمذی کی طویل حدیث)","",{"k":"ترمذی (3527)، ضعیف، البانی: 706، احمد (21512)۔"}],[9242,"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے، وہ کہتی ہیں کہ نبی کریم صلی اللہ علیہ وسلم جامع الفاظ کے ساتھ دعا کرنا پسند کرتے تھے اور اس کے سوا کوترک کر دیتے تھے۔ (ابوداؤد)","",{"k":"ابوداؤد (1482)، صحیح، البانی: 1315، احمد (27650)۔","e":"جامع دعا کا مطلب ہے کہ الفاظ کم ہوتے اور معانی زیادہ ہوتے اور آپ صلی اللہ علیہ وسلم ان دعاؤں کو پسند فرماتے تھے جن میں دنیا وآخرت کی خیر ہوتی جن میں تمام اچھی اغراض، اللہ کی ثنا اور آداب مسئلہ جمع ہوتے۔ (عون المعبود: ۱/۵۵۲)"}],[9243,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تمہاری دعا قبول ہوتی ہے جب تک کوئی شخص جلدی نہ کرے، وہ کہے کہ میں نے اپنے رب سے دعا مانگی اور میری دعا قبول نہ کی گئی۔‘‘","",{"k":"بخاری (6340)، مسلم (2735)، ابوداؤد (1484)، ترمذی (3387)، ابن ماجہ (3853)، احمد (8903)، مؤطا (495)۔","e":"دعا میں جلد بازی کرنے سے انسان اکتا جاتا ہے اور دعا کرنا چھوڑ دیتا ہے اور یہ بھی نقصان ہوتا ہے کہ اس سے انسان تصور کرتا ہے کہ میری دعا قبولیت کی مستحق تھی، نعوذ باللہ، اللہ بخل کر رہے ہیں حالانکہ وہ کریم ہے، قبولیت دعا میں کوئی رکاوٹ نہیں نہ ہی اس کی عطا و بخشش میں نقص آتا ہے۔ اس حدیث میں دعا کا ادب بتایا گیا ہے کہ انسان اپنی طلب و جستجو میں مگن رہے اور اللہ کے سامنے فروتنی اور سر تسلیم خم کرنے اور اظہار محتاجگی کرنے سے مایوس نہ ہو کیونکہ قبولیت دعا کی محرومی کا تصور دعا ہی سے محروم کر دیتا ہے۔ حالانکہ دعا کی توفیق رحمت الہی ہے۔ اس سے محروم ہونا گویا رحمت الہی سے عاری ہوتا ہے۔ (فتح الباری: ۱۱/۱۴۱)"}],[9244,"سیدنا جابر بن عبد اللہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: نہ بددعا کرو اپنی جان پر اور نہ بددعا کرو اپنی اولاد پر اور نہ بددعا کرو اپنے خادموں پر اور نہ بددعا کرو اپنے مالوں پر کہ وہ اللہ کی قبولیت کی گھڑی کے ساتھ موافق نہ ہو جس میں وہ انعام دیتا ہے پھر تمہاری دعا قبول ہو جائے۔ (ابوداؤد)","",{"k":"ابوداؤد (1532)، صحیح، البانی: 1356۔","e":"یعنی اپنے لیے ہلاکت کی دعا کرنا یا اولاد کے اندھا وغیرہ اپاہج ہونے کی بددعا کرنا، مال وغیرہ کے لیے موت کی بددعا کرنا، یہ ممانعت اس وجہ سے ہے کہ کبھی دعا کی قبولیت کی گھڑی ہوتی ہے وہ آ چکی ہو اور تمہاری بددعا قبول ہو جائے اور بعد میں پشیمانی ہو۔ (عون المعبود: ۱/۵۶۳)"}],[9245,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’چاہیے کہ تم میں سے ہر انسان اپنی ہر حاجت اپنے رب سے مانگے یہاں تک کہ جوتے کا تسمہ بھی رب سے مانگے اگر وہ ٹوٹ جائے۔‘‘","",{"k":"ترمذی (3973)، ضعیف، البانی: 735"}],[9246,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو اللہ سے سوال نہ کرے اللہ اس سے ناراض ہوتا ہے۔‘‘","",{"k":"ترمذی (3373)، حسن، البانی: 2676، ابن ماجہ (3827)۔"}],[9247,"سیدنا ابن مسعود رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ سے اس کا فضل مانگو، اللہ پسند کرتا ہے کہ اس سے سوال کیا جائے اور افضل عبادت کشادگی کا انتظار کرنا ہے۔‘‘ (یہ ترمذی کی مرویات ہیں)","",{"k":"ترمذی (3571)، ضعیف، البانی: 720۔","e":"اللہ تعالی پسند کرتے ہیں کہ بندے اس کے فضل کے طلب گار رہیں۔ جب بندے اس سے نہیں مانگتے تو اس کی رضا بندوں کو پسند نہ آئی یہی چیز اس کے غضب کا باعث ہے۔ غیر اللہ سے شکایت نہ کرنا اور آزمائش میں صبر کرنا اللہ کی قضا کو تسلیم کرنا ہے، اس لیے کشادگی کی امید رکھنا بہترین عبادت ہوئی لہذا کوئی معمولی چیز ہو یا بڑی ہو وہ اللہ سے ہی طلب کی جائے۔ (جائزۃ الاحوزی: ۴/۵۲۷)"}],[9248,"سیدنا جابر رضی اللہ عنہ سے روایت ہے، وہ کہتے ہیں: ایک عورت نے نبی صلی اللہ علیہ وسلم سے عرض کیا: میرے لیے اور میرے خاوند کے لیے دعا کیجیے، چنانچہ آپ صلی اللہ علیہ وسلم نے دعا کی: اللہ تجھ پر اور تیرے خاوند پر رحمت نازل فرمائے۔ (ابوداؤد)","",{"k":"ابوداؤد (1533)، صحیح، البانی: 1357۔"}],[9249,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس نے اس شخص پر بددعا کی جس نے اس پر ظلم کیا ہے تو اس نے اس کی مدد کر دی۔ (ترمذی)","",{"k":"ترمذی (3552)، ضعیف، البانی: 710۔","e":"ایک تو یہ ثابت ہوا کہ جب کوئی دعا کا مطالبہ کرے تو اس کے لیے دعا کی جائے اور یہ بھی ثابت ہوا دعا کے لیے صَلَّى اللهُ عَلَيْكَ (اللہ تجھ پر رحم کرے) غیر نبی کے لیے بھی کہا جا سکتا ہے جو تعظیم اور تبرک کے لیے ہے اور تعظیم کے لیے صلاۃ ہے وہ صرف نبی کے لیے خاص ہوتا ہے۔ (عون المعبود: ۱/۵۶۳)"}],[9250,"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے ایک عرب مرد کو فرمایا: جب تیرے اوپر امید آئے یا خوف آئے تو تم کس کی طرف التجا کرتے ہو؟ اس نے کہا: اللہ کی طرف۔ آپ نے فرمایا: جب وہ تمہاری دعا قبول کرتا ہے تو پھر کس کی طرف لوٹ جاتے ہو؟ اس نے کہا: اس چیز کی طرف جو آپ صلی اللہ علیہ وسلم جانتے ہیں۔ آپ نے فرمایا تم جانتے ہو اور عمل نہیں کرتے اور تم جانتے ہو عمل نہیں کرتے۔ تین بار فرمایا۔ (الأوسط سند کمزور)","",{"k":"طبرانی اوسط، وفیہ منصور بن صقیر وهو ضعیف وبقیۃ رجالہ ثقات، ہیثمی: 17217۔"}],[9251,"سیدنا ابو ایوب انصاری رضی اللہ عنہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم جب دعا فرماتے تو اپنے لیے دعا کرنے سے ابتدا کرتے۔ (الکبیر)","",{"k":"طبرانی کبیر: 4081، واسنادہ حسن، ہیثمی: 17238۔"}],[9252,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ تعالیٰ ایک مرد کے درجات بلند کرے گا تو وہ کہے گا: یہ میرے لیے کیسے حاصل ہوا تو اللہ تعالیٰ فرمائے گا: تیرے بیٹے نے تیرے لیے دعا کی ہے اس کی وجہ سے۔‘‘ (البزار)","",{"k":"بزار: 3141، ورجالہ رجال الصحیح غیر عاصم بن بہدلۃ وهو حسن الحدیث ولہ طرق فی التوبۃ فی استغفار الولد للوالدہ، ہیثمی: 17240۔"}],[9253,"سیدنا ابن مسعود رضی اللہ عنہ سے روایت ہے کہ اس نے ایک مرد کو کہا جب تو اللہ تعالیٰ سے بھلائی کا سوال کرے تو اس حال میں سوال نہ کر کہ تیرے ہاتھ میں پتھر ہو۔ (الکبیر، ایک راوی کا نام ذکر نہیں کیا)","",{"k":"طبرانی کبیر: 9217، برجل لم یسم وبقیۃ رجالہ رجال الصحیح، ہیثمی: 17242۔"}],[9254,"سیدنا ابو موسی رضی اللہ عنہ بیان کرتے ہیں کہ ایک مرد نے نبی صلی اللہ علیہ وسلم سے کوئی چیز مانگی پھر آپ نے فرمایا: کیا تو بنی اسرائیل کی بوڑھی کی مانند بھی نہ بن سکا تو آپ صلی اللہ علیہ وسلم کے اصحاب نے عرض کیا: بنی اسرائیل کی بوڑھی کیسی تھی اے اللہ کے رسول؟ آپ نے فرمایا: بیشک موسیٰ علیہ السلام نے بنی اسرائیل کو راتوں رات چلنے کا حکم دیا اور راستہ بھول گئے تو موسیٰ علیہ السلام نے بنی اسرائیل سے پوچھا کہ اس کی کیا وجہ ہے؟ تو ان کے علماء نے کہا کہ جب یوسف علیہ السلام پر موت کا وقت آیا تو اس نے ہم پر اللہ کے نام سے پختہ عہد لیا کہ جب ہم مصر سے نکلیں تو ان کی ہڈیاں ساتھ لیتے جائیں۔ موسیٰ علیہ السلام نے ان کو فرمایا: کیا یوسف علیہ السلام کی قبر میں سے کوئی جانتا ہے؟ انہوں نے کہا: بنی اسرائیل کی ایک بوڑھی کے سوا کوئی نہیں جانتا تو موسیٰ علیہ السلام نے اس کی طرف پیغام بھیجا اور فرمایا کہ مجھے یوسف علیہ السلام کی قبر بتا دو۔ اس عورت نے کہا کہ اللہ کی قسم! ہرگز نہیں بتاؤں گی یہاں تک کہ تو میرا حکم تسلیم کرے گا۔ موسیٰ علیہ السلام نے کہا: تیرا حکم کیا ہے؟ اس نے کہا: وہ یہ ہے کہ میں تیرے ساتھ جنت میں رہوں۔ موسیٰ علیہ السلام نے یہ وعدہ کرنا اپنے لیے بوجھ سمجھا تو ان کو حکم آیا کہ اس کو یہ وعدہ دے دے تو بوڑھی لوگوں کے ساتھ بحیرہ کے اس مقام پر گئی جہاں پانی صاف تھا اس نے کہا: یہ پانی بند کرو تو لوگوں نے پانی بند کیا۔ عورت نے کہا: یہ جگہ کھودو پس وہ جگہ کھود کر یوسف علیہ السلام کی ہڈیاں اس سرزمین سے نکالیں تو ان کے سامنے دن کی طرح روشن ہو گیا۔ (الموصلی، الکبیر بلفظہ)","",{"k":"طبرانی کبیر، الموصلی۔"}],[9255,"سیدنا ابریدہ رضی اللہ عنہ سے روایت ہے، وہ کہتے ہیں: نبی کریم صلی اللہ علیہ وسلم نے ایک مرد کو یوں کہتے ہوئے سنا: اے اللہ! میں تجھ سے اس لیے سوال کرتا ہوں کہ میں گواہی دیتا ہوں کہ تیرے بغیر کوئی حاجت روا نہیں ہے تو ایک ہے، بے نیاز ہے اور وہ ذات ہے جس نے کسی کو نہیں جنا اور نہ وہ جنا گیا ہے اور نہ اس کی کوئی برابری کرنے والا ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: قسم ہے اس ذات کی جس کے ہاتھ میں میری جان ہے کہ اس شخص نے اللہ تعالیٰ کے اس اسم اعظم کے ساتھ سوال کیا ہے جس کے ساتھ اس کو پکارا جائے تو وہ دعا قبول کرتا ہے اور اس کے ساتھ سوال کیا جائے تو وہ دیتا ہے۔ (ابوداؤد، ترمذی بلفظہ)","",{"k":"ترمذی (3475)۔ صحیح، البانی: 2763۔ ابن ماجہ (3857)۔"}],[9256,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے، وہ بیان کرتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ بیٹھا تھا کہ ایک شخص نے نماز پڑھی تو پھر دعا کی اے اللہ! میں تجھ سے سوال کرتا ہوں اس لیے کہ تیرے لیے حمد و ثنا ہے، تیرے سوا کوئی عبادت کے لائق نہیں ہے۔ تو بار بار احسان کرنے والا، ابتداء سے آسمانوں اور زمین کو پیدا کرنے والا، بڑائی والا اور کرم کرنے والا ہے۔ اے زندہ قائم رہنے والے! پس آپ صلی اللہ علیہ وسلم نے فرمایا: کیا جانتے ہو اس نے کس چیز کے ساتھ دعا کی ہے؟ انہوں نے عرض کی: اللہ اور اس کے رسول کو بہتر علم ہے۔ آپ نے فرمایا: اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! اس نے اللہ کے اسم اعظم کے ساتھ دعا کی ہے جس کے ساتھ دعا کی جائے تو اللہ قبول کرتا اور جب اس کے ساتھ سوال کیا جائے تو وہ دیتا ہے۔ (ابوداؤد، ترمذی اور نسائی)","",{"k":"نسائی (1300)۔ صحیح، البانی: 1233۔ ابوداؤد (1495)۔"}],[9257,"سیدہ اسماء بنت یزید رضی اللہ عنہا بیان کرتی ہیں کہ نبی صلی اللہ علیہ وسلم نے فرمایا: اللہ تعالیٰ کا اسم اعظم ان دو آیات میں ہے تمہارا معبود ایک ہی معبود ہے نہیں کوئی معبود مگر وہی، بڑا مہربان رحم کرنے والا اور دوسری سورت آل عمران کی پہلی آیت: الم اللہ ہے اس کے سوا کوئی معبود نہیں، وہ زندہ، قائم رکھنے والا ہے۔ (ابوداؤد، ترمذی)","",{"k":"ابوداؤد (1496)۔ حسن، البانی: 1327۔ ترمذی (3478)۔ ابن ماجہ (3855)۔ احمد (27064)۔"}],[9258,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ وہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم سیدہ عائشہ رضی اللہ عنہا کے پاس گھر گئے تو اس نے عرض کیا کہ میرے ماں باپ آپ صلی اللہ علیہ وسلم پر قربان ہوں آپ مجھے اسم اعظم بتادیں جس کے ذریعے دعا کی جائے تو اللہ تعالیٰ قبول کرتا ہے اور جس کے ذریعے سوال کیا جائے تو وہ دے دیتا ہے۔ آپ صلی اللہ علیہ وسلم نے اس سے منہ پھیر دیا تو وہ اٹھیں اور وضو کیا اور یوں کہا: اے اللہ! میں تجھ سے بھلائی کا سوال کرتی ہوں خواہ میں جس کو جانتی ہوں یا جس کو میں نہیں جانتی اور میں تیرے اسم اعظم کے وسیلے سے سوال کرتی ہوں جس کے ساتھ تجھے پکارا جائے تو تو قبول کرتا ہے اور تجھ سے سوال کیا جائے تو تو دیتا ہے۔ تو آپ صلی اللہ علیہ وسلم نے فرمایا: اللہ کی قسم! وہ اسم ان اسماء میں ہے۔ (الأوسط سند ضعیف)","",{"k":"طبرانی اوسط وفیہ محمد بن عبداللہ العصری وہو ضعیف، ہیثمی: 17262۔","e":"ان احادیث سے ثابت ہوا کہ اللہ کے لیے اسم اعظم ہے جس کے ساتھ دعا کی جائے تو وہ قبول کرتا ہے، اس میں یہ دلیل بھی ہے کہ اللہ کا ہر اسم جو پورے اخلاص کے ساتھ ذکر کیا جائے غیر اللہ سے اس میں اعراض کیا گیا ہو تو وہ اسم اعظم ہے۔ اسم اعظم کے تعین میں تقریباً چالیس اقوال ہیں جس کو بھی احادیث میں اسم اعظم قرار دیا گیا ہے وہ اسم اعظم ہے۔ (جائزۃ الاحوذی: ۴/۲۷۶)"}],[9259,"سیدنا ابوامامہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: وہ اس جس سے دعا کی جائے تو قبول کی جاتی ہے وہ تین سورتوں میں ہے۔ البقرۃ، آل عمران اور سورۃ طہ۔ (ابن ماجہ)","",{"k":"ابن ماجہ (3856)۔ حسن، البانی: 3110۔"}],[9260,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے دعا کی: یا اللہ! میں تجھ سے سوال کرتا ہوں تیرے پاک اچھے بابرکت نام کے ساتھ جو تجھے محبوب ہے، جس کے ساتھ تجھے پکارا جائے تو تو قبول کرتا ہے اور جس کے وسیلے سے تجھ سے سوال کیا جائے تو تو دیتا ہے اور جب اس کے ساتھ رحمت طلب کی جائے تو تو رحمت دیتا ہے۔ آپ صلی اللہ علیہ وسلم نے ایک دن فرمایا: اے عائشہ! تجھے علم ہے کہ اللہ تعالیٰ نے مجھے وہ اسم بتا دیا ہے جس کے ساتھ دعا کی جائے تو وہ قبول کرتا ہے۔ میں نے عرض کی: یا رسول اللہ! میرے ماں باپ آپ پر فدا ہوں وہ مجھے تعلیم فرما دیجیے۔ فرمایا: اے عائشہ! وہ تیرے لیے مناسب نہیں ہے۔ میں تھوڑی دیر علیحدہ ہو کر بیٹھ رہی اور میں پھر اٹھی اور آپ صلی اللہ علیہ وسلم کے سر کو بوسہ دیا اور پھر عرض کی: یا رسول اللہ! آپ مجھے اس کی تعلیم دیں۔ فرمایا: اے عائشہ! وہ تیرے لیے مناسب نہیں ہے کہ میں تجھے اس کی تعلیم دوں۔ تیرے لیے یہ مناسب نہیں ہے کہ اس کے ساتھ تو دنیا کی کوئی چیز طلب کرے۔ پس میں اٹھی، میں نے وضو کیا اور دو رکعات پڑھیں اور میں نے کہا: اے اللہ! میں تجھے بَر رحیم کہہ کر پکارتی ہوں اور تجھے تیرے تمام اسمائے حسنیٰ کے ساتھ پکارتی ہوں خواہ میں ان کو جانتی ہوں یا میں ان کو نہیں جانتی ہوں کہ تو مجھے بخش دے اور میرے اوپر رحمت نازل فرما۔ وہ کہتی ہیں آپ صلی اللہ علیہ وسلم ہنس دیے اور پھر فرمایا: وہ انہی اسماء میں ہے جو تو نے ابھی ذکر کیے ہیں۔ (ابن ماجہ)","",{"k":"ابن ماجہ (3859)۔ ضعیف، البانی: 841۔"}],[9261,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: اللہ تعالیٰ کے نانوے نام ہیں جو ان کو یاد کرے گا وہ جنت میں داخل ہوگا۔ اللہ ایک ہے اور وہ طاق کو پسند کرتا ہے۔ (الشیخان)","",{"k":"مسلم (2677)۔ بخاری (2736)۔ ترمذی (3507)۔ ابن ماجہ (3860)۔ دارمی (1580)۔ احمد (10307)۔"}],[9262,"سیدنا ابو ہریرہ رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اللہ تعالیٰ کے نانوے نام ہیں جو یاد کرے گا وہ جنت میں داخل ہوگا۔ (۱) وہ اللہ ہے جس کے بغیر کوئی معبود نہیں (۲) بڑا رحم کرنے والا (۳) مہربان (۴) حقیقی بادشاہ (۵) نہایت پاک (۶) بے عیب و سلامت (۷) امن دینے والا (۸) محافظ ونگہبان (۹) غالب بے مثل (۱۰) بگڑے کاموں کو درست کرنے والا (۱۱) نہایت بڑائی والا (۱۲) پیدا کرنے والا (۱۳) درست کر کے پیدا کرنے والا (۱۴) صورت بنانے والا (۱۵) بخشنے والا (۱۶) سب پر غالب (۱۷) بہت دینے والا (۱۸) رزق کا مالک (۱۹) کھولنے اور حکم کرنے والا (۲۰) سب کچھ جاننے والا (۲۱) تنگ کرنے والا (۲۲) وسیع کرنے والا پست کرنے والا، بلند کرنے والا۔ عزت دینے والا ذلت دینے والا، سننے والا، دیکھنے والا، حکم دینے، فیصلہ کرنے والا حق کے مطابق، انصاف کرنے والا نرمی کرنے والا، لطف کرنے والا خبر رکھنے والا، بردبار بڑا عظمت والا، بہت بخشنے والا، قدر دان، بلند تر ذات بہت بڑا، محفوظ رکھنے والا، قوت دینے والا، کفایت کرنے والا، بزرگ ذات بڑا سخی، نگہبانی کرنے والا، دعائیں قبول کرنے والا، وسیع طاقتوں والا، دانا، دوست رکھنے والا شریف ذات مردوں کو اٹھانے والا، ہر چیز پر مطلع ذات سچا معبود کارساز، قوت والا تمام امور پر طاقت رکھنے والا مدد گار دوست اپنی تعریف کرنے والا، ہر چیز کو اپنے علم میں شمار کرنے والا، اول بار پیدا کرنے والا، دوسرے بار پیدا کرنے والا، زندہ کرنے والا، مارنے والا، ہمیشہ زندہ قائم رہنے والا، غیر محتاج، ہر چیز کا مالک ایک منفرد بے نیاز قدرت والا، قدرت کا اظہار کرنے والا، قریب میں جگہ دینے والا، مؤخر کرنے والا، اوّل آخر ظاہر، مخفی مالک بلند مرتبہ، احسان کرنے والا، توبہ قبول کرنے والا، انتقام لینے والا، معاف کرنے والا، بہت شفقت کرنے والا، ہر چیز کا مالک بزرگی اور بخشش کا مالک، بڑا عادل ہر چیز سے بے پروا غنی کرنے والا، باز رکھنے والا ضرر پہنچانے والا نفع پہنچانے والا روشن کرنے والا، راہ دکھانے والا، بغیر مثال کے پیدا کرنے والا ہمیشہ باقی رہنے والا، ہر چیز کا مالک، ہر چیز کو ہدایت دینے والا، صبر کرنے والا اور قزوینی (ابن ماجہ) کی کمزور سند کے ساتھ روایت ہے اللہ کے ننانوے نام ہیں سو سے ایک کم اللہ ایک ہے طاق ہے اور طاق کو پسند کرتا ہے جو ان کو یاد کرے گا وہ جنت میں داخل ہوگا۔ اللہ ایک بے نیاز اول آخر ظاہر باطن خالق باری، تصویر بنانے والا، مالک حق سلامتی والا، امن دینے والا، حفاظت کرنے والا، غالب قدرت والا، سننے والا دیکھنے والا جاننے والا عظمت والا، بارہ تعالیٰ [بلند رہنے والا] بزرگی والا، خوبصورت ہمیشہ زندہ قائم قادر غالب بلند حکمت والا، قریب کرنے والا، دعا قبول کرنے والا غنی کرنے والا، بہت دینے والا، محبت کرنے والا، قدردان بے پروا ہر چیز کا مالک والی ہدایت دینے والا، معاف کرنے والا بخشنے والا، بردبار بڑا سخی توبہ قبول کرنے والا، بزرگ ذات والی حاضر بیان کرنے والا، صاحب ذلی شفقت کرنے والا، مہربان ابتدا کرنے والا، دوبارہ پیدا کرنے والا اٹھانے والا، وارث قوت والا بہت شدت والا ضرر دینے والا نفع دینے والا ہمیشہ رہنے والا، بچانے والا پست کرنے والا، بلند کرنے والا، کشادہ کرنے والا، عزت دینے والا، ذلیل کرنے والا، انصاف والا، رزق کا مالک مضبوط طاقت ور، قائم رہنے والا، دائم رہنے والا، محافظ کارساز دیکھنے والا، سننے والا، دینے والا، نہ دینے والا، زندہ کرنے والا مارنے والا، ھادی ہمیشہ کفایت کرنے والا، علم والا، سچا نور روشن کرنے والا، مکمل ذات قدیم ذات، طاق، ایک بے نیاز، جس نے نہیں جنا، نہ وہ جنا گیا اور نہ کوئی اس کی برابری کرنے والا ہے۔ زہیر رحمہ اللہ نے کہا: ہمیں بہت سے اہل علم کا یہ قول پہنچا ہے کہ ان اسماء کو ان کلمات سے شروع کیا جائے۔ نہیں کوئی معبود مگر اللہ ایک، اس کا کوئی شریک نہیں اس کے لیے بادشاہی ہے، اسی کی حمد و ثنا ہے اسی کے ہاتھ میں بھلائی ہے، وہ ہر چیز پر قادر ہے، نہیں کوئی عبادت کے لائق مگر اللہ اور اس کے اچھے اچھے نام ہیں۔","",{"k":"ترمذی (3507)۔ ضعیف بسرد الاسماء: 696۔ بخاری (2736)۔ مسلم (2677)۔ ابن ماجہ (3860)۔ احمد (10154)۔","e":"ان احادیث میں جو اسمائے حسنیٰ کی فہرست ہے یہ علمائے کرام کی ہے، مرفوع ثابت نہیں۔ دوسری بات یہ ہے کہ جس نے ان اسمائے حسنیٰ کو زبانی یاد کیا اور پھر انہیں شمار کیا اور ان کے مطابق عمل کیا، عقیدہ و عمل بنایا وہ جنت میں داخل ہوگا۔ اور ان احادیث کا یہ مطلب نہیں کہ صرف ننانوے ہی اسمائے حسنیٰ ہیں، اس سے زیادہ نہیں، بلکہ ننانوے سے زیادہ بھی ہیں مگر ننانوے پڑھنے سے اور ان کے حقائق کے مطابق عمل کرنے سے جنت میں داخلہ ملتا ہے، تعداد ان کی ننانوے سے زیادہ ہے۔ انہیں طاق شمار کرنے کی حکمت یہ بتائی جاتی ہے کہ یہ وتر تعداد ہے اور وتر تعداد افضل ہے۔ ایک قول یہ بھی ہے کہ یہ تعبدی حکم ہے۔ حدیث نے جتنی تعداد بتائی ہے بس اس کی پابندی کی جائے جیسا کہ رات اور دن میں پانچ نمازیں ہیں جو کہ طاق ہیں حکمت اس کی کیا ہے اس کا ہمیں پتہ نہیں۔ (انجاز الحاجہ: ۱۱/۱۶۵)"}],[9263,"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم جب نماز میں تکبیر اولیٰ کہتے تو تھوڑی دیر خاموش رہتے تھے، پھر قراءت شروع کرتے تو میں نے عرض کی: یا رسول اللہ! میرے ماں باپ آپ صلی اللہ علیہ وسلم پر قربان ہوں میں نے تکبیر اور قراءت کے درمیان آپ کا خاموش رہنا تو دیکھا ہے آپ اس وقت کیا پڑھتے ہیں؟ آپ نے فرمایا: یوں کہتا ہوں: اے اللہ! مجھے خطاؤں سے اس طرح صاف کر دے جیسا سفید کپڑے کو میل سے صاف کیا جاتا ہے۔ اے اللہ! میرے خطائیں برف، پانی اور اولوں کے ساتھ دھو دے۔ (الشیخان) ابو داؤد اور نسائی نے اس دعا کے شروع میں یہ کلمات اضافہ کیے ہیں: اے اللہ! میرے درمیان اور میری خطاؤں کے درمیان اتنا بُعد اور دوری پیدا کر دے جس قدر تو نے مشرق اور مغرب کے درمیان بُعد پیدا کیا ہے۔","",{"k":"مسلم (598)۔ بخاری (744)۔ ابوداؤد (781)۔ نسائی (894)۔ ابن ماجہ (805)۔ دارمی (1244)۔ احمد (78124)۔","e":"اس دعا کی اس مقام کے ساتھ بہت ہی عمدہ مناسبت ہے۔ یہ مقام مناجات کا ہے۔ نمازی اللہ کی بارگاہ میں یہ تمنا لیے حاضر ہے کہ میرے گناہ مٹ جائیں اور گناہوں کے اور اس کے درمیان بہت دور تک فاصلہ ہو جائے، اور اس کا دل پاکیزگی کا آئینہ بن جائے۔ عام مشاہدہ ہے کہ میل کچیل گرم پانی سے زیادہ صاف ہوتی ہے مگر اس دعا میں برف اور اولے وغیرہ ٹھنڈی چیزوں سے صفائی طلب کی گئی ہے۔ وجہ یہ ہے کہ گناہ اپنے اندر ایک قسم کی تپش رکھتے ہیں، جن کی شعلہ باری انسان کو جلا کر خاکستر بنا دیتی ہے۔ اس تپش سوزاں کو بچھانے کے لیے یہ ٹھنڈی اشیاء ہی موزوں اور مناسب ہیں۔ اس حدیث سے ثابت ہوا کہ نماز میں یہ دعائے استفتاح پڑھنا مستحب ہے اور اس دعا کا مقام تکبیر تحریمہ کے بعد اور سورت فاتحہ کی قراءت سے پہلے ہے اور یہ دعا ہر نماز کی صرف پہلی رکعت میں پڑھنی ہے۔ یہ بھی پتہ چلا کہ صحابہ کرام رضی اللہ عنہم رسول اکرم صلی اللہ علیہ وسلم کی حرکات و سکنات پر کس قدر گہری نگاہ رکھتے تھے، یہی وجہ ہے کہ اللہ پاک نے ان ہی قدسی نفوس کے ذریعے اپنے دین کی حفاظت فرمائی ہے۔ (تفہیم الاسلام: ۱/۲۹۷)"}],[9264,"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے کہ ہم نبی کریم صلی اللہ علیہ وسلم کے ساتھ نماز پڑھ رہے تھے کہ لوگوں میں سے ایک نے آکر کہا: اللہ بڑا ہے بہت بڑا اور اس کی تعریف ہے بہت زیادہ اور اللہ پاک ہے اپنی صفات کے ساتھ صبح و شام۔ نبی صلی اللہ علیہ وسلم نے فرمایا: یہ کلمات کہنے والا کون ہے؟ لوگوں میں سے ایک مرد نے عرض کی: یا رسول اللہ! میں ہوں۔ فرمایا: مجھے تعجب پیدا ہوا کہ ان کلمات کے لیے آسمان کے دروازے کھول دیے گئے ہیں۔ سیدنا ابن عمر رضی اللہ عنہ نے کہا: جب سے میں نے یہ کلمات آپ صلی اللہ علیہ وسلم سے سنے ہیں میں نے ان کو ترک نہیں کیا۔ (مسلم، ترمذی، نسائی)","",{"k":"مسلم (601)۔ ترمذی (3592)۔ نسائی (885)۔ احمد (4613)۔"}],[9265,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نماز پڑھا رہے تھے کہ ایک آدمی آیا، اس کا سانس تیز چل رہا تھا۔ اس نے کہا: اللہ سب سے بڑا ہے اللہ کی حمد و ثنا سے بہت زیادہ اور بابرکت اور پاک۔ جب آپ صلی اللہ علیہ وسلم نے نماز پوری کی تو فرمایا: یہ کلمات کہنے والا کون ہے؟ تو لوگ خوف کے مارے خاموش رہے تو آپ صلی اللہ علیہ وسلم نے فرمایا: کہنے والے نے غلط بات نہیں کہی تو ایک مرد نے کہا: یا رسول اللہ! میں نے کہا ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: میں نے بارہ فرشتے دیکھے، ہر ایک ان میں سے آگے بڑھ کر ان کلمات کو اٹھانے کی کوشش کرتا تھا تاکہ وہ اٹھائے۔ (مسلم، ابوداؤد، نسائی)","",{"k":"نسائی (901)۔ صحیح، البانی: 866۔ مسلم (600)۔ ابوداؤد (763)۔ احمد (12548)۔"}],[9266,"سیدنا جبیر بن مطعم رضی اللہ عنہ بیان کرتے ہیں کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم کو نماز پڑھتے دیکھا۔ آپ صلی اللہ علیہ وسلم نے اس اس طرح کہا: اللہ بہت بڑا ہے، اللہ بہت بڑا ہے، اللہ کے لیے بہت زیادہ حمد و ثنا ہے، تین بار، پاک ہے اللہ صبح و شام تین بار۔ میں اللہ کی پناہ مانگتا ہوں شیطان مردود کے تکبر سے، اس کے شعر پڑھنے سے اور اس کے مرنے سے (ابوداؤد)","",{"k":"ابوداؤد (764)۔ ضعیف، البانی: 160۔ احمد (16319)۔","e":"یہ تینوں دعائیں تکبیر تحریمہ کے بعد فرض نمازوں اور نفل نمازوں میں پڑھی جا سکتی ہیں حمداً کثیرا طیبا الخ والی رکوع سے سر اٹھا کر پڑھنے کا ذکر بھی آتا ہے۔ قَدْ وَرَدَ فِي الْأَحَادِيثِ الصَّحِيحَةِ الْأَعْدَادُ مِنَ الْأَذْكَارِ وَالْأَدْعِيَةِ فِي اسْتِفْتَاحِ الصَّلَاةِ بَيْنَ التَّكْبِيرِ وَالْقِرَاءَةِ فِي الْمَكْتُوبَةِ وَغَيْرِهَا. (التعليقات السلفية: ۱/۱۰۵) ’’صحیح احادیث میں وارد یہ اذکار اور دعائیں جو استفتاح کے وقت پڑھی جاتی ہیں یہ فرض نمازوں اور غیر فرض نمازوں سب کے لیے ہیں، انہیں تہجد یا نوافل کے ساتھ خاص قرار دینے کا دعویٰ درست نہیں۔‘‘ صبح و شام کے ساتھ تسبیح کرنے کی وجہ ہمیشہ کے لیے تسبیح ہے۔ اتنے ہی الفاظ تھے، ان کی تعداد کے مطابق فرشتے آئے تھے۔ گویا ایک ایک لفظ کو اٹھانے کے لیے فرشتہ آیا تھا۔"}],[9267,"سیدنا جابر بن عبد اللہ رضی اللہ عنہ سے روایت منقول ہے، وہ کہتے ہیں نبی صلی اللہ علیہ وسلم جب نماز شروع کرتے تھے تو تکبیر کہتے تھے، پھر یہ دعا پڑھتے تھے: بے شک میری نماز، میری قربانی، میری زندگی اور میری موت اللہ کے لیے ہے جو سب جہانوں کا رب ہے۔ اس کا کوئی شریک نہیں ہے اور مجھے اسی بات کا حکم دیا گیا ہے اور میں پہلا مسلمان ہوں۔ اے اللہ! مجھے اچھے اعمال کے لیے ہدایت عطا کر اور اچھے اخلاق کے لیے۔ ان کی اچھائی کے لیے تیرے سوا کوئی بھی ہدایت نہیں دے گا اور مجھے بُرے اعمال اور بُرے اخلاق سے بچا، ان کی بدی سے تیرے سوا کوئی نہیں بچائے گا۔ (نسائی)","",{"k":"نسائی (896)۔ صحیح، البانی: 861۔"}],[9268,"سیدہ عائشہ رضی اللہ عنہا سے مروی ہے کہ وہ کہتی ہیں: جب نبی کریم صلی اللہ علیہ وسلم نماز شروع کرتے تو آپ صلی اللہ علیہ وسلم اس طرح کہتے تھے: پاک ہے تو اے اللہ! تیری صفت وثنا ہے، تیرا نام با برکت ہے، تیری شان بلند ہے اور تیرے سوا کوئی معبود نہیں ہے۔ (ترمذی و ابوداود)","",{"k":"ابوداؤد (776)۔ صحیح، البانی: 702۔ ترمذی (243)۔ ابن ماجہ (806)۔"}],[9269,"سیدنا سعد رضی اللہ عنہ سے روایت ہے، وہ کہتے ہیں کہ ایک مرد نماز کے لیے آیا تو نبی کریم صلی اللہ علیہ وسلم نماز پڑھ رہے تھے۔ جب وہ صف میں گیا تو اس نے کہا: اے اللہ! میں تجھ سے اس چیز کا سوال کرتا ہوں جو چیز تو اپنے نیک بندوں کو دیتا ہے۔ آپ نے سلام پھیرا تو فرمایا: ابھی ابھی کلام کس نے کیا ہے؟ تو اس نے کہا: میں نے، اے اللہ کے رسول! آپ نے فرمایا: تیرے گھوڑے کی پچھاڑ کاٹی جائیں گی اور تو اللہ کی راہ میں شہادت پائے گا۔ (رزین)","",{"k":"رزین۔"}],[9270,"سیدنا علی بن ابی طالب رضی اللہ عنہ سے روایت ہے کہ وہ کہتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم جب نماز کے لیے کھڑے ہوتے تو فرماتے: میں نے اپنے چہرے کو اس ذات کے سپرد کیا یکسو ہو کر جس نے زمین و آسمان کو پیدا کیا اور میں شرک کرنے والوں میں سے نہیں ہوں۔ میری نماز، میری قربانی، میری زندگی اور میری موت اللہ کے لیے ہے جو سب جہانوں کو پالنے والا ہے، اس کا کوئی شریک نہیں ہے۔ مجھے اسی بات کا حکم دیا گیا ہے اور میں مسلمانوں میں سے ہوں۔ اے اللہ! تو بادشاہ ہے تیرے سوا کوئی معبود نہیں ہے تو میرا رب ہے اور میں تیرا بندہ ہوں۔ میں نے اپنی جان پر ظلم کیا ہے اور میں اپنے گناہوں کا اعتراف کرتا ہوں۔ تو میرے سب گناہ بخش دے تیرے سوا گناہوں کو کوئی نہیں بخشتا ہے اور مجھے اچھے اخلاق کی ہدایت عطا فرما۔ اچھے اخلاق کی ہدایت تیرے سوا کوئی نہیں دیتا ہے اور مجھ سے برے اخلاق دُور کر دے۔ تیرے سوا بُرے اخلاق کو مجھ سے دور کرنے والا کوئی نہیں ہے۔ میں تیرے دربار میں حاضر ہوں۔ ہر خیر تیری طرف سے ہے اور شر کی نسبت تیری طرف نہیں کی جاتی ہے۔ میں تیرے ساتھ ہوں، تیری طرف متوجہ ہوا ہوں۔ تو برکت دینے والا ہے اور تو بہت بلند ہے۔ میں تجھ سے مغفرت طلب کرتا ہوں اور تیری طرف رجوع کرتا ہوں۔ اور جب رکوع کرتے تو اس میں کہتے: اے اللہ! میں نے تیرے لیے رکوع کیا، میں تیرے ساتھ ایمان لایا اور تیرا حکم تسلیم کیا۔ میرے کان، میری آنکھیں، میرا مغز، میری ہڈیاں اور میرے پٹھے تیرے سامنے عاجزی کر رہے ہیں۔ اور جب سر اٹھاتے تو کہتے اے اللہ! اے ہمارے رب! تیرے لیے حمد و ثنا ہے آسمانوں کو زمین کو اور ان کے درمیان جو بھی کسی اور ہر اس چیز کو بھر کر جس کو اس کے بعد تو چاہے۔ اور جب سجدہ کرتے تو اس میں کہتے: اے اللہ! میں نے تیرے لیے سجدہ کیا، تیرے ساتھ ایمان لایا اور تیرا حکم تسلیم کیا۔ میرے چہرے نے اس ذات کو سجدہ کیا جس نے اس کو پیدا کیا اور اس کی صورت بنائی، اس کے کان اور آنکھیں بنائیں۔ برکت والا ہے اللہ، بہت اچھا پیدا کرنے والا اور پھر تشہد اور سلام کے درمیان یوں کہتے تھے: اے اللہ! مجھے بخش دے جو میں نے پہلے گناہ کیے یا جو مؤخر کیے اور جو میں نے پوشیدہ کیے اور جو میں نے ظاہر کیے اور جو میں نے اسراف کیا اور جو کچھ تو مجھ سے زیادہ بہتر جانتا ہے۔ تو ہی اول ہے، تو ہی آخر ہے۔ تیرے سوا کوئی معبود نہیں ہے۔ (مسلم، ابوداؤد، ترمذی اور نسائی)","",{"k":"مسلم (771)۔ ابوداؤد (760)۔ ترمذی (3422)۔ نسائی (897)۔ ابن ماجہ (864)۔ دارمی (1238)۔ احمد (805)۔","e":"یہ ساری دعائیں پڑھنی جائز ہیں، خواہ ان کو جمع کر کے پڑھا جائے یا علیحدہ علیحدہ پڑھا جائے، یا ان میں سے کسی ایک کا انتخاب کر لیا جائے۔ یہ بھی ثابت ہوا کہ قراءت سے پہلے اعوذ باللہ پڑھنا نہایت ضروری ہے، وجہ یہ ہے کہ نماز اور قراءت کے ذریعے انسان قربت کی راہوں کا سالک ہوتا ہے، اسے درجات علیا پر فائز کیا جاتا ہے اور تزکیہ نفس ہوتا ہے۔ یہ چیز شیطان کو ایک لمحہ کے لیے نہیں بھاتی۔ وہ انسان کو خواہشات پر ابھارتا ہے۔ نماز اور قرآن پڑھنے سے سینے کی بیماریاں دور ہوتی ہیں۔ ان سے قلب انسانی میں نور ہدایت اور علم و خیر جاگزیں ہوتے ہیں جبکہ یہ فضائل اور مناقب شیطان کی طبع نارسا پر ناگوار گزرتے ہیں، اس لیے نماز وغیرہ میں قرآن پاک کی تلاوت کا ارادہ کرنے سے پہلے مردود شیطان سے اللہ کی پناہ طلب کی جائے۔ (تفہیم الاسلام: ۱/۲۹۹)"}],[9271,"سیدنا ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے پردہ دور کیا اور لوگ ابوبکر صدیق رضی اللہ عنہ کے پیچھے صفوں میں تھے، آپ نے فرمایا: لوگو! نبوت کی بشارتوں میں سے صرف نیک خواب ہی باقی رہ گئے ہیں جو ایک مسلمان دیکھتا ہے یا اسے دکھایا جاتا ہے۔ خبردار رہو مجھے رکوع اور سجود کی حالت میں قرآن پڑھنے سے منع کیا گیا ہے۔ رکوع میں رب تعالیٰ کی عظمت بیان کرو اور سجدے میں پوری کوشش سے دعا مانگو۔ زیادہ امید ہے کہ دعا تمہاری قبول ہوگی۔ (مسلم، ابوداؤد، نسائی)","",{"k":"مسلم (479)۔ ابوداؤد (876)۔ نسائی (1045)۔ ابن ماجہ (3899)۔ دارمی (1325)۔ احمد (1903)۔"}],[9272,"سیدنا عوف بن مالک رضی اللہ عنہ سے منقول ہے کہ میں نبی کریم صلی اللہ علیہ وسلم کے ساتھ کھڑا ہوا۔ جب آپ صلی اللہ علیہ وسلم نے رکوع کیا تو سورۃ البقرۃ کے اندازے کے برابر رکوع میں کہتے رہے: پاک ہے قوت اور بادشاہی والا، بڑائی اور عظمت والا۔ (نسائی)","",{"k":"نسائی (1049)۔ صحیح، البانی: 2004۔ ابوداؤد (873)۔ احمد (23460)۔"}],[9273,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں: نبی کریم صلی اللہ علیہ وسلم بکثرت رکوع و سجود میں کہا کرتے تھے: پاک ہے تو اے ہمارے اللہ! پروردگار ہمارے۔ تیری حمد وثنا ہے، اے اللہ! مجھے بخش دے۔ آپ قرآن کا مفہوم ملحوظ رکھتے تھے۔ (الشیخان، ابوداؤد، نسائی)","",{"k":"بخاری (817)۔ مسلم (484)۔ ابوداؤد (877)۔ نسائی (1122)۔ ابن ماجہ (889)۔ احمد (25539)۔"}],[9274,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ نبی کریم صلی اللہ علیہ وسلم رکوع اور سجود میں فرمایا کرتے تھے: پاک ہے وہ پاکیزہ ذات جو رب ہے ملائکہ اور روح کا۔ (مسلم، ابوداؤد، نسائی)","",{"k":"ابوداؤد (872)۔ صحیح، البانی: 775۔ مسلم (487)۔ نسائی (1048)۔ احمد (25539)۔"}],[9275,"سیدنا عقبہ بن عامر رضی اللہ عنہ سے منقول ہے کہ جب یہ آیت نازل ہوئی ﴿اور تسبیح بیان کیجیے اپنے عظمت والے رب کی﴾ تو نبی کریم صلی اللہ علیہ وسلم نے فرمایا: اس کو تم اپنے رکوع میں بیان کیا کرو۔ اور جب یہ آیت نازل ہوئی ﴿تسبیح بیان کیجیے اپنے رب اعلیٰ کی﴾ تو آپ صلی اللہ علیہ وسلم نے فرمایا: اس کی تم اپنے سجود میں تعمیل کرو۔ پس جب آپ صلی اللہ علیہ وسلم رکوع کرتے تو کہتے: پاک ہے میرا رب عظمت والا اس کی حمدوثنا کے ساتھ تین بار اور جب سجدہ کرتے تو تین بار کہتے: پاک ہے اللہ جو میرا رب اعلیٰ ہے، اس کی حمدوثنا کے ساتھ۔ (ابوداؤد)","",{"k":"ابوداؤد (869)۔ ضعیف، البانی: 184۔ ابن ماجہ (887)۔ دارمی (1305)۔ احمد (16961)۔","e":"شریعت اسلامیہ جو بھی پابندی لگاتی ہے وہ عین حکمت کا تقاضا ہوتا ہے، رکوع اور سجدے کی حالت نہایت ہی تذلل اور خضوع کی آئینہ دار ہے۔ آدمی خود فرش خاک پر بچھ جاتا ہے اور صدائیں عزت و شرف کے حقیقی مالک کی کبریائی کی بلند کرتا ہے، لہذا اس حالت بے بسی کے مناسب حال یہی ہے کہ تسبیح ومناجات کی جائے اور دعا والتجاء میں ہمت بھر کوشش کرے کیونکہ یہ وقت قبولیت دعا کا ہے۔ قرآن مجید کلام الہی ہے۔ اس کی عظمت و جلالت شان کا تقاضا یہی ہے کہ اس قدر حالت زار اور ذلت و پستی میں اسے نہ پڑھا جائے، اس طرح اس کی رفعت شان اور شرافت میں فرق پڑتا ہے، اس حالت میں تعظیم رب کی ترغیب ہی بہتر ہے۔ یہ بھی معلوم ہوا کہ سجدہ کی حالت میں دنیا و آخرت کی خیر خواہی کی کوئی بھی دعا کی جا سکتی ہے اور دنیا و آخرت کی کسی بھی شر سے پناہ طلب کی جا سکتی ہے اور سجدہ ورکوع دعا کی قبولیت کے مقام ہیں۔ ان دعاؤں پر غور فرمائیں، پیغمبر علیہ السلام کے اگلے پچھلے گناہ معاف ہیں، پھر بھی شان ربوبیت کی تعظیم کرتے ہیں اور اپنی عبودیت کا حق ادا کرتے ہوئے سرنگوں نظر آتے ہیں اور کس قدر تیز روی سے فرمان الہی اپناتے ہیں۔ (تفہیم الاسلام: ۱/۳۲۷)"}],[9276,"سیدنا ابن ابی اوفی رضی اللہ عنہ بیان کرتے ہیں کہ جب نبی کریم صلی اللہ علیہ وسلم رکوع سے اپنا سر اٹھاتے تو کہتے: سنا ہے اللہ نے اس کو جس نے اس کی حمد بیان کی۔ اے اللہ! اے ہمارے رب! تیرے لیے حمد ہے آسمان اور زمین بھر کر اور ہر چیز کو بھر کر جس کو تو چاہے اس کے بعد اے اللہ! مجھے برف کے ساتھ، اولوں کے ساتھ اور ٹھنڈے پانی کے ساتھ پاک کر دے۔ اے اللہ! مجھے گناہوں اور خطاؤں سے اس طرح پاک کر دے جیسے سفید کپڑا میل سے پاک کیا جاتا ہے۔ (ابوداؤد، ترمذی، مسلم)","",{"k":"مسلم (476)۔ ابوداؤد (846)۔ ترمذی (3547)۔ نسائی (402)۔ ابن ماجہ (878)۔ احمد (18658)۔"}],[9277,"سیدنا ابوسعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم جب رکوع سے سر اٹھاتے تو کہتے: اے اللہ! تیرے لیے حمد ہے زمین آسمان بھر کر اور ہر وہ چیز بھر کو جو اس کے بعد تو چاہے، تو ثنا کے قابل ہے، تیری بڑائی ہے زیادہ مقدار ہے اس صفت و ثنا کا جو بندہ کہتا ہے اور ہم سب تیرے بندے ہیں۔ اے اللہ! کوئی روکنے والا نہیں ہے۔ جو چیز تو عطا کردے اور کوئی دینے والا نہیں ہے جس چیز کو تو منع کر دے کسی بڑے کی بڑائی تیرے بالمقابل کوئی کام نہیں دیتی۔ (مسلم، ابوداؤد اور نسائی)","",{"k":"مسلم (477)۔ ابوداؤد (847)۔ نسائی (1068)۔ ابن ماجہ (87)۔ دارمی (1313)۔ احمد (11418)۔"}],[9278,"سیدنا رفاعہ بن رافع رضی اللہ عنہ سے مروی ہے کہ ہم نبی کریم صلی اللہ علیہ وسلم کے پیچھے تھے۔ جب آپ نے رکوع سے سر اٹھایا تو فرمایا: اللہ نے اس شخص کو سنا جس نے اس کی حمد بیان کیا۔ اور آپ صلی اللہ علیہ وسلم کے پیچھے ایک مرد نے کہا: اے ہمارے رب! تیرے لیے حمد و ثنا ہے، بہت زیادہ، بہت پاکیزہ اور برکت دی ہوئی۔ جب آپ صلی اللہ علیہ وسلم نے سلام پھیرا تو فرمایا: کلام کرنے والا کون ہے؟ اس نے کہا: میں ہوں۔ آپ نے فرمایا: میں نے تیس سے زیادہ فرشتے دیکھے ہیں جو ایک دوسرے سے آگے بڑھتے تھے کہ ان کلمات کو سب سے پہلے کون لکھے۔","",{"k":"بخاری (799)۔ ابوداؤد (770)۔ نسائی (931)۔ احمد (18517)۔ مؤطا (491)۔"}],[9279,"ایک روایت میں ہے انہوں نے کہا: میں نے نبی کریم صلی اللہ علیہ وسلم کے پیچھے نماز پڑھی تو میں نے کہا: سب تعریفیں اللہ کے لیے ہیں بہت زیادہ، بہت پاکیزہ، اس میں بہت برکت ڈالی گئی اور اس پر بہت برکت دی گئی جیسا ہمارا رب پسند کرتا اور راضی ہوتا ہے۔ جب آپ صلی اللہ علیہ وسلم نے سلام پھیرا تو فرمایا: نماز میں کلام کرنے والا کون ہے؟ آپ صلی اللہ علیہ وسلم نے دوبارہ فرمایا: پھر تیسری بار بھی فرمایا تو کوئی نہ بولا۔ پس رفاعہ رضی اللہ عنہ نے کہا: میں ہوں۔ آپ نے فرمایا: تو نے کیسے کہا؟ میں نے کہا: میں نے کہا ہے: سب تعریفیں زیادہ حمد و ثناء پاکیزہ اس میں برکت دی ہوئی اس پر برکت نازل کی ہوئی اللہ ہی کے لیے ہے جیسا ہمارا رب پسند کرتا اور راضی ہوتا ہے پس نبی صلی اللہ علیہ وسلم نے فرمایا: قسم اس ذات کی جس کے ہاتھ میں میری جان ہے! تیس سے زیادہ فرشتے ایک دوسرے سے آگے بڑھے کہ ان میں سے کون ان کلمات کو لے کر اوپر جائے۔ (مسلم کے سوا چھ نے بیان کیا)","",{"k":"ترمذی (404)، حسن، البانی: 331، بخاری (799)، ابوداؤد (770)، نسائی (931)، احمد (18517)، مؤطا (491)۔"}],[9280,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب امام کہے: اللہ نے اس شخص کو سنا جس نے اس کی حمد بیان کی تو تم کہو: اے اللہ! ہمارے پروردگار تیرے لیے حمد ہے، جس شخص کا قول فرشتوں کے قول کے موافق ہو گیا اس کے لیے بخش دیا گیا جو پہلے وہ گناہ کر چکا ہے۔","",{"k":"بخاری (796)، مسلم (409)، ابوداؤد (848)، ترمذی (267)، نسائی (1063)، ابن ماجہ (875)، احمد (9121)۔","e":"ان احادیث سے ثابت ہوا کہ نماز فرض ہو یا نفل ہو ان دعاؤں کا پڑھنا مسنون ہے، اور یہ بھی ثابت ہوا کہ قومہ میں یہ دعائیں پڑھی جائیں، اکٹھی کر لیں یا ایک پڑھ لیں جائز ہیں۔ اس سے ان لوگوں کی بھی تردید ہوتی ہے جو قومہ میں صحیح طریقے سے کھڑے بھی نہیں ہوتے اور فوراً سجدہ میں چلے جاتے ہیں۔ ان دعاؤں کی تاثیر پر غور فرمائیں، بندہ اپنے رب کی کبریائی بیان کرتا ہے اور عرش تا فرش جو اس منعم حقیقی کے انعامات کی بارش ہے ان کی انتہائی شکر کی جدو جہد کرتا ہے، مگر پھر بھی اپنی بے بسی کا اظہار کرتا ہے اور حمد کا یہ خوگر اس قدر اڑان لیتا ہے کہ بلندی و وسعت کی اس حد تک چلا جاتا ہے کہ اس سے اوپر جانا محال ہے، کہتا ہے: اے مولائے حقیقی! میں ایک تو تیرا ایک عاجز و درماندہ غلام ہوں، تیری جتنی منشا ہے میں اتنی تعریف کرتا ہوں۔ ان میں اللہ کی قدرت کاملہ اور عظمت قاہرہ اور سلطنت غالبہ اور اس کی سطوت و جلالت کے سامنے خود سپردگی کا درس ہے کہ دنیوی جاہ و جلال، بزرگی اور عالی حسب و نسب کوئی کام نہیں آتا۔ (تفہیم الاسلام: ۱/۳۳۲) یہ بھی ثابت ہوا کہ آمین کی مانند سمع اللہ لمن حمدہ الخ امام و مقتدی دونوں کہیں۔ یہ بھی ثابت ہوا کہ جو مقتدی کہتے ہیں، فرشتے بھی وہی کہتے ہیں۔ فرشتوں کی موافقت کرنا بندوں کے لیے عظیم خوبی ہے۔ (فتح الباری: ۲/۲۸۳)"}],[9281,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم اپنے سجدے میں کہتے تھے اے اللہ! میرے تمام گناہ معاف فرما چھوٹے بھی، بڑے بھی، پہلے بھی، پچھلے بھی، پوشیدہ بھی اور جو ظاہر ہیں وہ بھی۔ (مسلم اور ابوداؤد)","",{"k":"مسلم (483)، ابوداؤد (878)۔"}],[9282,"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے، وہ کہتی ہیں: میں نے نبی کریم صلی اللہ علیہ وسلم کو بستر پر نہ پایا، چنانچہ میں نے آپ صلی اللہ علیہ وسلم کو ہاتھ لگا کر تلاش کیا تو میرا ہاتھ آپ کے دو قدموں کے تلوے پر پڑا۔ آپ صلی اللہ علیہ وسلم سجدے میں تھے اور دونوں پاؤں کھڑے تھے اور آپ کہہ رہے تھے: اے اللہ! میری تیری رضا کی پناہ لیتا ہوں تیرے غصے سے اور تیری معافی کی پناہ لیتا ہوں، تیری سزا سے اور تیری پناہ لیتا ہوں تجھ سے۔ میں تیری ثنا پوری نہیں کر سکتا جیسے تو نے خود اپنی ثنا بیان کی ہے۔ (مسلم)","",{"k":"مسلم (486)، ابوداؤد (879)، ترمذی (3493)، نسائی (1130)، ابن ماجہ (3841)، احمد (23791)۔"}],[9283,"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ میں نے ایک رات نبی صلی اللہ علیہ وسلم کو مفقود (گم) پایا تو میں نے گمان کیا کہ آپ اپنی کسی بیوی کے پاس گئے ہوں گے۔ میں نے تلاش کیا اور پھر میں لوٹ آئی۔ دیکھا تو آپ صلی اللہ علیہ وسلم رکوع یا سجدے میں کہہ رہے تھے: پاک ہے تو اے اللہ! تیری حمد و ثنا ہے، تیرے سوا کوئی معبود نہیں ہے۔ میں نے کہا: میرے ماں باپ آپ صلی اللہ علیہ وسلم پر فدا ہوں۔ آپ کسی اور شان میں ہیں اور میں کسی اور بات میں ہوں۔","",{"k":"نسائی (3962)، صحیح، البانی: 3698، مسلم (485)۔","e":"دعا میں چھوٹے گناہوں کا پہلے ذکر ہے اور بڑوں کی معافی کا بعد میں ذکر ہے۔ وجہ یہ ہے کہ صغیرہ گناہوں پر اصرار کبیرہ گناہوں پر آمادہ کر دیتا ہے اور اول و آخر گناہوں کی معافی سے مقصد یہ ہے کہ سارے گناہوں کا احاطہ مراد ہے، اللہ کے لیے تو سب کچھ ظاہر ہے کوئی بھی پوشیدہ نہیں۔ یہ انسان کے مطابق کہا گیا ہے۔ اللہ خفیہ کو بھی جانتا ہے۔ ان دعاؤں میں عبادت کے حق میں تقصیر کا اعتراف بھی ہے اور اس سے استغفار کیا گیا ہے۔ سزا اور ناراضی سے یہ دلیل ہے کہ جس طرح اللہ کی طرف خیر کی نسبت ہو جاتی ہے شر کی بھی ہو جاتی ہے۔ (عون المعبود: ۱/۳۲۸) اور یہ بھی ثابت ہوا کہ سجدے میں پاؤں کی ایڑیاں ملا کر رکھیں۔"}],[9284,"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے، وہ کہتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم دو سجدوں کے درمیان یہ دعا پڑھتے تھے: اے اللہ! مجھے بخش دے، میرے اوپر رحمت فرما، مجھے ہدایت دے، مجھے معافی دے اور مجھے رزق عطا فرما۔ (ترمذی اور ابوداود)","",{"k":"ترمذی (284)، صحیح، البانی: 233، ابوداؤد (850)، ابن ماجہ (898)۔","e":"یعنی میری اطاعت میں جو کوتاہی ہے وہ معاف کر دے، میری عبادت قبول کر کے مجھ پر رحم فرما اور مجھے دونوں جہاں کی بلاؤں اور ظاہری و باطنی امراض سے عافیت دے اور دین حق پر مجھے ثابت رکھ اور صالح اعمال کی ہدایت دے اور مجھے اچھا رزق دے اور دنیا و آخرت میں درجات عالیہ کی توفیق دے۔ یہ حدیث دلالت کرتی ہے کہ دو سجدوں کے درمیان یہ دعا مسنون ہے۔ یہ فرض اور سنتوں میں اور نوافل میں پڑھنی مسنون ہے۔ (عون المعبود: ۱/۳۱۶) یہ دعا دنیا و آخرت کی خیرات کی جامع ہے جو اسے نہیں پڑھتے وہ بہت ساری برکات سے محروم ہیں۔ (تفہیم الاسلام: ۱/۳۴۰)"}],[9285,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کوئی شخص تشہد پڑھ چکے تو چار چیزوں سے اللہ تعالیٰ کی پناہ مانگے اور کہے: اے اللہ! میں جہنم کے عذاب سے تیری پناہ مانگتا ہوں اور قبر کے عذاب سے اور زندگی اور موت کے فتنے سے اور مسیح الدجال کے فتنے سے۔‘‘ (شیخین، ابوداود، نسائی)","",{"k":"مسلم (588)، بخاری (1377)، ابوداؤد (983)، ترمذی (3604)، نسائی (5518)، ابن ماجہ (909)، دارمی (1344)، احمد (27280)۔"}],[9286,"سیدنا جابر بن عبداللہ رضی اللہ عنہ سے مروی ہے، وہ کہتے ہیں نبی کریم صلی اللہ علیہ وسلم اپنی نماز میں تشہد کے بعد فرماتے تھے ’’بہتر کلام اللہ کا کلام ہے اور بہتر رہنمائی محمد صلی اللہ علیہ وسلم کی رہنمائی ہے۔‘‘ (نسائی)","",{"k":"نسائی (1311)، صحیح الاسناد، البانی: 1243، احمد (14022)۔"}],[9287,"سیدنا ابن مسعود رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم ہمیں یہ دعا تشہد کے بعد کے لیے تعلیم فرماتے تھے: اے اللہ! نیکی پر ہمارے دلوں کے درمیان الفت ڈال دے اور ہمارے آپس کے معاملات کی اصلاح کر دے، ہمیں سلامتی کے راستوں پر چلا دے، ہمیں ظلمات (تاریکیاں) سے نجات دے کر نور میں پہنچا دے اور ہمیں ہر فحش سے دور کر دے خواہ وہ ظاہر ہو یا وہ باطن ہو۔ ہمارے کانوں میں، ہماری آنکھوں میں، ہمارے دلوں میں اور ہماری ازواج میں برکت ڈال اور ہم پر رجوع کر۔ تو توبہ قبول کرنے والا مہربان ہے اور ہمیں اپنی نعمتوں کا شکر کرنے والے بنا اور اس پر متوجہ ہونے والے بنا اور اپنی نعمتیں ہم پر مکمل کر دے۔ (رزین)","",{"k":"رزین۔","e":"یہ دعائیں تشہد کے بعد درود شریف کے بعد پڑھی جائیں۔ ان میں نبی صلی اللہ علیہ وسلم کی سیرت کو سب سے بہتر قرار دیا گیا ہے اور چار چیزوں سے پناہ مانگی گئی ہے، یہ قبولیت دعا کا وقت ہے، دوزخ کے المناک شعلے اور قبر کی وحشت ناکی اور زندگی اور موت کے فتنوں کی المناکی اور مسیح دجال کی مکر سازی کا تصور بھی دل کو ہلا دیتا ہے۔ اس لیے ان چاروں سے کائنات کی سب سے بڑی پناہ گاہ ڈھونڈی گئی ہے۔ اس سے یہ بھی ثابت ہوا کہ عذاب و ثواب قبر ہے، اس کا انکار قرآن و حدیث کا انکار ہے۔ (تفہیم الاسلام: ۱/۳۵۹)"}],[9288,"سیدنا معاذ بن جبل رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے ان کا ہاتھ پکڑ کر فرمایا: اے معاذ! اللہ کی قسم! میں تجھے پسند کرتا ہوں میں تجھے وصیت کرتا ہوں۔ اے معاذ! ہر نماز کے بعد یہ کہنے سے نہ رکنا: اے اللہ! اپنے ذکر، اپنے شکر اور اچھی طرح اپنی عبادت کرنے میں میری مدد فرما۔ (ابوداود اور نسائی)","",{"k":"ابوداؤد (1522)، صحیح، البانی: 1347، نسائی (303)، احمد (21621)۔","e":"اس دعا میں دنیا و آخرت کی خیر کے حصول کی توفیق مانگی گئی ہے لہذا فرض نماز کے بعد اسے ترک کرنا مناسب نہیں۔ جو کیفیت حدیث میں درج ہے یہ اس کی اہمیت بتاتی ہے، محبوب رہبر محبّ صادق سے ملے تو اندازہ لگائیں یہ دعا کا ہدیہ کس قدر جاذب نظر اور باعث کشش ہے اور پڑھنے والے کا مقام کس قدر بلند اور قابل رشک ہے۔ (تفہیم الاسلام: ۱/۳۶۷)"}],[9289,"سیدنا شداد بن اوس رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم اپنی نماز میں کہا کرتے تھے۔ اے اللہ! معاملے میں ثابت قدمی، ہدایت میں پختگی کا سوال کرتا ہوں اور میں سوال کرتا ہوں، تیری نعمت کے شکر کا اور اچھے طریقے سے تیری عبادت کا اور میں سوال کرتا ہوں تندرست دل کا، سچی زبان کا میں سوال کرتا ہوں ہر بھلائی کے بارے میں جو تو جانتا ہے اور میں ہر اس شر سے تیری پناہ مانگتا ہوں جو تیرے علم میں ہے۔ اور میں بخشش مانگتا ہوں ہر اس چیز کے بارے میں جو تو جانتا ہے۔‘‘","",{"k":"نسائی (1304)۔ ضعیف، البانی: 70۔ ترمذی (3407)۔"}],[9290,"سیدنا قیس بن عباد رضی اللہ عنہ سے روایت ہے کہ سیدنا عمار بن یاسر رضی اللہ عنہ نے لوگوں کو ہلکی پھلکی نماز پڑھائی تو لوگوں نے اس کو مکروہ سمجھا تو انہوں نے کہا: کیا میں نے رکوع، سجود مکمل نہیں کیا؟ لوگوں نے کہا: ایسا تو کیا ہے۔ تو انہوں نے کہا: میں نے نماز میں وہ دعا کی ہے جو نبی کریم صلی اللہ علیہ وسلم کیا کرتے تھے۔ اے اللہ! اپنے علم غیب کے وسیلے سے اور مخلوق پر اپنی قدرت کے وسیلے سے مجھے زندہ رکھ جب تک میرا زندہ رہنا میرے لیے بہتر ہے اور مجھے وفات دے دے جب تیرے علم میں میرے لیے وفات بہتر ہے۔ یا اللہ! باطن اور ظاہر میں میں تیری خشیت کا سوال کرتا ہوں اور رضا اور غصے سے کلمہ اخلاص کہنے کا سوال کرتا ہوں۔ اور فقر اور مال داری میں درمیانہ طریقہ اختیار کرنے کا سوال کرتا ہوں اور میں تجھ سے ایسی نعمت کا سوال کرتا ہوں جو کبھی ختم نہ ہو اور تقدیر وارد ہونے کے بعد اس سے راضی ہونے کا سوال کرتا ہوں۔ اور آنکھوں کی ٹھنڈک کا سوال کرتا ہوں جو ختم نہ ہو اور ٹھنڈی زندگی کا سوال کرتا ہوں مرنے کے بعد اور تیرے چہرہ اقدس کی طرف لذت کے ساتھ دیکھنے کا سوال کرتا ہوں اور تیری ملاقات کی طرف شوق رکھنے کا سوال کرتا ہوں جس میں نہ تو ضرر ہو، نہ کوئی تکلیف ہو اور نہ گمراہ کرنے والا فتنہ ہو۔ اے اللہ! ہمیں ایمان کی زینت کے ساتھ ہمیں مزین کر دے اور ہمیں ہدایت یافتہ ہادی بنا دے۔‘‘ (یہ دونوں روایات نسائی کی ہیں)","",{"k":"نسائی (1306)۔ صحیح، البانی: 1237۔ احمد (17859)۔"}],[9291,"سیدہ عائشہ رضی اللہ عنہا زوجہ نبی صلی اللہ علیہ وسلم سے روایت ہے، وہ کہتی ہیں کہ نبی کریم صلی اللہ علیہ وسلم نماز میں یہ دعا کیا کرتے تھے۔ اے اللہ! میں قبر کے عذاب سے تیری پناہ مانگتا ہوں اور مسیح الدجال کے فتنے سے تیری پناہ مانگتا ہوں اور میں زندگی اور موت کے فتنے سے تیری پناہ مانگتا ہوں۔ اے اللہ! میں قرض اور گناہ سے تیری پناہ مانگتا ہوں۔ ایک کہنے والے نے آپ صلی اللہ علیہ وسلم سے کہا: آپ صلی اللہ علیہ وسلم قرض سے بہت پناہ مانگتے ہیں۔ آپ نے فرمایا: آدمی جب مقروض ہو جاتا ہے بات کرتا ہے تو جھوٹ بولتا ہے اور وعدہ کرتا ہے تو اس کے خلاف کرتا ہے۔‘‘ (شیخین، ابوداؤد، نسائی)","",{"k":"بخاری (833)۔ مسلم (589)۔ ابوداؤد (880)۔ نسائی (5454)۔ ابن ماجہ (3838)۔ احمد (25544)۔"}],[9292,"سیدنا ابوبکر صدیق رضی اللہ عنہ بیان کرتے ہیں: میں نے عرض کیا: یا رسول اللہ! مجھے ایسی دعا کی تعلیم دیجیے جو میں نماز میں دعا کروں۔ آپ نے فرمایا: کہا کرو: اے اللہ! میں نے اپنے نفس پر بہت ظلم کیا ہے اور گناہوں کا بخشنے والا تیرے سوا کوئی نہیں ہے، چنانچہ اپنے پاس سے مجھے مغفرت عطا فرما اور میرے اوپر رحمت نازل کر، بے شک تو بخشنے والا مہربان ہے۔‘‘ (شیخین، ترمذی، نسائی)","",{"k":"بخاری (834)۔ مسلم (2705)۔ ترمذی (3531)۔ نسائی (1302)۔ ابن ماجہ (3835)۔ احمد (29)۔"}],[9293,"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ جب نبی کریم صلی اللہ علیہ وسلم رات کی نماز سے فارغ ہوئے تو میں نے آپ صلی اللہ علیہ وسلم کو یہ دعا کرتے سنا: اے اللہ! میں تیری طرف سے ایسی رحمت کا تجھ سے سوال کرتا ہوں جس کے ذریعے تو میرے دل کو ہدایت دے دے اور میرے امور جمع کر دے اور میری پراگندگی دور کر دے اور میرے مسافر کو اس کے سبب واپس لائے اور میرے حاضر کو اس کے ذریعے بلند کر دے اور اس کے ساتھ میرے اعمال پاکیزہ کر دے اور اس کے ذریعے میری ہدایت کا الہام کر دے اور میری الفت بحال کر دے اور اس کے ذریعے مجھے ہر بدی سے دور کر دے۔ اے اللہ! مجھے ایسا ایمان اور یقین عطا کر جس کے بعد کفر نہ ہو، ایسی رحمت عطا کر جس کے ساتھ دنیا اور آخرت میں تیری طرف عزت حاصل کروں۔ اے اللہ! قضاء وقدر کی کامیابی کا سوال کرتا ہوں۔ شہداء کا رتبہ چاہتا ہوں سعادت مند لوگوں کی زندگی کا طلب گار ہوں اور دشمنوں پر فتح کا طلب گار ہوں۔ اے اللہ! میں تیرے سامنے اپنی حاجت رکھتا ہوں اور اپنی کوتاہی فکر اور ضعف عمل کو تیرے سامنے لاتا ہوں۔ اور میں تیری رحمت کا محتاج ہوں اس لیے تجھ سے سوال کرتا ہوں۔ اے تمام امور کے فیصلے کرنے والے! اے سینوں کو شفا دینے والے! جیسے سمندروں کے درمیان تو پردے کر دیتا ہے اسی طرح مجھے آگ کے عذاب سے پناہ دے دے۔ موت طلب کرنے کے فتنے سے اور قبر کے فتنے سے محفوظ فرما۔ یا اللہ! تیری وہ نعمت جس سے میری رائے کوتاہ رہی اور دعا اس کے ذکر کو نہ پہنچی اور میری نیت بھی نہیں پہنچی اور وہ بھلائی تو نے اپنے بندوں کے لیے تیار کی ہے یا اپنے بندوں کو تو عنایت کرے گا تو میں اس نعمت کے لیے بھی تیری طرف التجا کرتا ہوں اور اس کا تجھ سے سوال کرتا ہوں۔ تیری رحمت کے وسیلے سے اے سب جہانوں کے رب اے اللہ! اے مضبوط رسی والے! اے طاقت ور حکم والے! میں وعدے کے دن امن کا سوال کرتا ہوں اور یوم الخلود میں جنت کا طلب گار ہوں۔ مجھے ان لوگوں کے ساتھ کر دے جو تیری حاضری میں رکوع و سجود کرنے والے ہیں، جو وعدے پورے کرنے والے ہیں، یقیناً تو مہربان محبت کرنے والا ہے اور جو تیرا ارادہ ہو تو وہی کرتا ہے۔ اے اللہ! ہمیں ہادی مہدی بنا دے نہ ہم خود گمراہ ہوں نہ دوسروں کو گمراہ کرنے والے ہوں۔ ہم تیرے دوستوں کے ساتھ صلح رکھنے والے ہو جائیں اور تیرے دشمنوں کے ساتھ جنگ کرنے والے بن جائیں۔ ہم تیری محبت کے ساتھ ہوں۔ جو تجھ سے محبت کرے اس سے ہم محبت کریں اور تیری دشمنی کے ساتھ دشمنی کریں جو تیرا مخالف ہو۔ اے اللہ! یہ میری دعا ہے اور قبول کرنا تیری اختیار میں ہے۔ اور یہ میری کوشش ہے اور تیری اوپر توکل ہے۔ اے اللہ! میرے لیے نور کر دے میرے دل میں، میری قبر میں نور کر، میرے سامنے نور کر، میرے پیچھے نور کر، میرے دائیں نور کر، میرے بائیں نور کر، نور میرے اوپر کر، نور میرے نیچے کر، نور کر میرے کانوں میں، نور کر میری آنکھوں میں، نور کر دے میرے بالوں میں، میرے چہرے میں نور کر دے۔ میرے گوشت میں نور کر دے، میرے خون میں نور کر دے، میرے مغز میں نور کر دے اور میری ہڈیوں میں نور کر دے۔ اے اللہ! مجھے نور میں بڑا کر دے اور مجھے نور عطا کرا ور کر دے میرے لیے نور۔ پاک ہے وہ ذات جو اپنی عزت کے ساتھ مہربان ہے اور اسی کے ساتھ کہا پاک ہے وہ، بڑائی اور بزرگی اس کا لباس ہے۔ پاک ہے وہ جس کے سوا کے لیے تسبیح و تقدیس مناسب نہیں ہے۔ پاک ہے بڑائی والا بہت سخاوت کرنے والا۔‘‘ (ترمذی)","",{"k":"ترمذی (3419)۔ ضعیف الاسناد، البانی: 678۔","e":"پہلی حدیث میں چٹی سے پناہ کا ذکر ہے۔ پہلی چار چیزوں کی وضاحت اوپر ہو چکی ہے، چٹی کا مطلب ہے قرض چڑھ جائے یا دو آدمیوں کی صلح کے لیے تاوان اٹھا لینا یا کاروبار کا بیٹھ جانا۔ حدیث میں اس کے نقصان سے خبر دار کیا گیا ہے۔ ایک چیز ذہن میں الجھاؤ پیدا کرتی ہے۔ آپ صلی اللہ علیہ وسلم کے تمام گناہوں کی معافی کا اعلان ہو چکا تھا، معصوم تھے پھر اتنی دعائیں کیوں فرماتے تھے؟ اس کا جواب یہ ہے کہ آپ نے امت کو تعلیم دی ہے اور تواضع کے اظہار کے لیے اور بندگی ثابت کرنے کے لیے دعا کرتے تھے اور امت کو ترغیب دی ہے کہ مغفرت کے باوجود اگر میں دعا کر رہا ہوں تو جو گنہگار ہوا سے تو بہت زیادہ اللہ کی بارگاہ میں دست بدعا ہونا چاہیے۔ ۲۔ اللهم انی ظلمت والی دعا میں اللہ کی وحدانیت کا اقرار ہے اور مغفرت کی طلب ہے اور یہ طلب رکھنے والوں کی تعریف ہے کیونکہ اللہ کی مغفرت کا مطالبہ ہے۔ اللہ پاک کی ذات گرامی جتنی بڑی ہے اس کی مغفرت کا ہدیہ بھی اس کے برابر ہے اور یہ تاکید ہے کہ میں اگر مغفرت کا اہل نہیں تو اپنی مہربانی سے مجھے بخش دے۔ اس میں عالم سے تعلیم حاصل کرنے کی ترغیب بھی ہے۔ (فتح الباری: ۲/۳۲۱)"}],[9294,"سیدہ عائشہ رضی اللہ عنہا کا بیان ہے کہ نبی کریم صلی اللہ علیہ وسلم نماز سے سلام پھیر کر تین بار استغفار کرتے تھے اور کہتے تھے: اے اللہ! تو سلامتی دینے والا ہے اور سلامتی تیری طرف سے ہے، تو برکت والا ہے۔ اے عظمت والے، اکرام والے! اوزاعی کو کہا گیا: استغفار کیسے ہے؟ انہوں نے کہا: کہتے تھے: استغفر اللہ، استغفر اللہ۔‘‘ (مسلم، ابوداؤد، نسائی)","",{"k":"ابوداؤد (1512)۔ صحیح، البانی: 1339۔ مسلم (592)۔ ترمذی (298)۔ نسائی (1338)۔ ابن ماجہ (924)۔ دارمی (1347)۔ احمد (24979)۔","e":"سلام پھیرنے کے بعد تین مرتبہ استغفر اللہ کہنے کے بعد یہ دعا کرنا مسنون ہے اور اس کے بعد امام مقتدیوں کی جانب منہ کر لے۔ نماز کے بعد اس دعا کا اور دیگر مذکور اذکار کو پڑھنا مستحب ہے، اور یہ الفاظ اللہ کی بارگاہ میں بہت محبوب ہیں۔\nایک حدیث میں آتا ہے: یا ذا الجلال والاکرام کے ساتھ اللہ کی پناہ میں آؤ۔ (ترمذی وغیرہ) ایک آدمی دعا کر رہا تھا: یا ذا الجلال والاکرام، آپ صلی اللہ علیہ وسلم پاس سے گزرے تو فرمایا: اس کی دعا قبول ہوگی۔ (توضیح الاحکام: ۲/۳۰۲) بعض لوگ اس میں اضافہ کرتے ہیں: والیک یرجع اسلام حیینا ربنا بالسلام، یہ اضافہ حدیث سے ثابت نہیں یہ ریشم میں ٹاٹ کا پیوند لگانے والی بات ہے۔ (تفہیم الاسلام: ۱/۳۶۵)"}],[9295,"ابو زبیر رضی اللہ عنہ سے مروی ہے کہ وہ جب بھی نماز سے سلام پھیرتے تو یہ کہتے: نہیں کوئی عبادت کے لائق مگر اللہ وہ ایک ہے، اس کا کوئی شریک نہیں ہے۔ اس کے لیے بادشاہت ہے اور اس کے لیے حمد و ثنا ہے اور وہ ہر چیز پر قادر ہے۔ بدی سے بچنے اور نیکی حاصل کرنے کی توفیق اللہ ہی کی طرف سے ہے۔ کوئی معبود نہیں ہے مگر اللہ ہم نہیں عبادت کرتے مگر اللہ کی۔ اسی کی طرف سے نعمت ہے، اسی کا فضل ہے اور اسی کے لیے دین۔ خواہ کافر ناپسند کریں۔ اور انہوں نے کہا ان کلمات کے ساتھ ہر فرض نماز کے بعد نبی کریم صلی اللہ علیہ وسلم تہلیل کرتے تھے۔ (مسلم، ابوداود، نسائی)","",{"k":"مسلم (594)۔ ابوداؤد (1506)۔ نسائی (1239)۔ احمد (15673)۔","e":"نماز کے بعد پڑھنے سے مراد نماز کے آخر وقت میں یا نماز کے سلام کے بعد یہ دعا پڑھتے تھے۔ یہ حدیث دلالت کرتی ہے کہ نماز کے بعد یہ دعا پڑھنا مسنون ہے اور اسے ایک مرتبہ پڑھنا ہے کیونکہ تکرار کی دلیل نہیں۔ (عون المعبود: ۱/۵۵۷)"}],[9296,"سیدنا کعب بن عجرہ رضی اللہ عنہ بیان کرتے ہیں رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: معقبات ہیں یعنی فرائض کے بعد پڑھنے کے کلمات ہیں۔ ان کا پڑھنے والا ناکام نہیں رہتا یا فرمایا: ان کو معمول بنانے والا۔ ہر نماز کے بعد تینتیس بار تسبیح کہنا، تینتیس بار تحمید کہنا اور چونتیس بار تکبیر کہنا۔ (مسلم، ترمذی، ابوداؤد)","",{"k":"مسلم (596)۔ ترمذی (3412)۔ نسائی (1349)۔"}],[9297,"سیدنا زید بن ثابت رضی اللہ عنہ سے مروی ہے کہ ایک انصاری کو خواب میں کہا گیا: تمہیں رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا ہے ہر نماز کے بعد تینتیس بار تسبیح کہنے، تینتیس بار تحمید کہنے اور چونتیس بار تکبیر کہنے کا؟ اس نے کہا: ہاں! اس نے کہا: ان کلمات کو پچیس پچیس بار کردو اور ان کے ساتھ تہلیل شامل کرو۔ فجر کو نبی کریم صلی اللہ علیہ وسلم کی خدمت میں آیا اور آپ صلی اللہ علیہ وسلم سے اس کا ذکر کیا تو آپ نے فرمایا: اسی طرح کرلو۔","",{"k":"نسائی (1350)۔ صحیح، البانی: 1279۔ دارمی (1354)۔"}],[9298,"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ وہ مرفوع بیان کرتے ہیں جس نے صبح کی نماز کے بعد سو بار تسبیح اور سو بار تہلیل کی تو اللہ تعالیٰ اس کے گناہ بخش دے گا خواہ وہ سمندر کی جھاگ کے برابر ہوں۔ (یہ دونوں سنائی کی ہیں)","",{"k":"نسائی (1354)۔ صحیح الاسناد، البانی: 1282۔ بخاری (6405)۔ مسلم (2691)۔ ترمذی (3466)۔ ابن ماجہ (3812)۔ احمد (7948)۔ مؤطا (487)۔"}],[9299,"سیدنا اور انہی سے روایت ہے کہ فقراء مہاجرین نبی کریم صلی اللہ علیہ وسلم کے پاس آئے اور عرض کیا: مالدار لوگوں نے اعلیٰ درجات بھی لے لیے اور دائمی نعمتیں بھی حاصل کیں۔ آپ نے فرمایا وہ کیسے؟ انہوں نے عرض کیا: وہ نماز پڑھتے ہیں جیسے ہم پڑھتے ہیں اور وہ روزے رکھتے ہیں جیسے ہم رکھتے ہیں اور وہ صدقہ دیتے ہیں اور ہم صدقہ نہیں دیتے اور وہ غلام آزاد کرتے ہیں اور ہم نہیں کرتے تو آپ صلی اللہ علیہ وسلم نے فرمایا: کیا میں تمہیں وہ چیز نہ بتا دوں جس کے ذریعے تم آگے جانے والوں کو پہنچ جاؤ گے اور تم سے پیچھے چلنے والے تم سے آگے نہیں بڑھ سکیں گے اور تم سے پھر کوئی افضل نہ ہوگا مگر وہ شخص جو تمہارے جیسا عمل کرے گا؟ انہوں نے عرض کیا: جی ہاں، اے اللہ کے رسول! آپ نے فرمایا: سبحان اللہ، الحمد للہ اور اللہ اکبر ہر نماز کے بعد تینتیس، تینتیس بار پڑھو۔ ابو صالح نے کہا: پھر فقراء مہاجرین نبی کریم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور انہوں نے کہا: ہمارے مال دار بھائیوں نے وہ سن لیا جس پر ہم نے عمل کیا اور انہوں نے بھی اس کے مثل عمل کیا۔ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: یہ اللہ کا فضل ہے جسے چاہے دیتا ہے۔ سمی کہتے ہیں: میں نے اپنے گھر کے لوگوں کو یہ حدیث بیان کی تو انہوں نے کہا تجھے بھول لگی ہے آپ صلی اللہ علیہ وسلم نے تو یہ فرمایا تھا: تینتیس بار سبحان اللہ تینتیس بار الحمد للہ اور چونتیس بار اللہ اکبر کہو تو میں ابو صالح کے پاس گیا تو اس نے کہا: اللہ اکبر سبحان اللہ الحمد للہ پھر کہا: اللہ اکبر، سبحان اللہ اور الحمد للہ یہ سب تینتیس تینتیس بار ہی ہیں یہاں تک کہ وہ پہنچا تینتیس تینتیس بار کر","",{"k":"مسلم (595)۔ بخاری (843)۔ ابوداؤد (1504)۔ دارمی (1353)۔ احمد (7202)۔"}],[9300,"ایک روایت میں ہے: تم ہر نماز کے بعد پڑھو سبحان اللہ، الحمد للہ، اللہ اکبر دس دس بار۔","",{"k":"بخاری (6329)۔ مسلم (595)۔ ابوداؤد (1504)۔ ابن ماجہ (927)۔ دارمی (1353)۔ احمد (8616)۔ مؤطا (488)۔"}],[9301,"اور ایک روایت میں ہے: گیارہ گیارہ اور گیارہ مرتبہ۔"],[9302,"اور دوسری ایک روایت ہے: جس نے تسبیح کہی ہر نماز کے بعد تینتیس مرتبہ، تحمید کہی ہر نماز کے بعد تینتیس مرتبہ اور اللہ اکبر کہا تینتیس مرتبہ اور اس کلمے کے ساتھ سو کا عدد پورا کیا۔ نہیں کوئی معبود مگر اللہ وہ ایک ہے اس کا کوئی شریک نہیں ہے اس کے لیے بادشاہی ہے اور اسی کے لیے حمد و ثنا ہے اور وہ ہر چیز پر قادر ہے۔ تو اس کے گناہ بخش دیے جاتے ہیں خواہ وہ سمندر کی جھاگ کے برابر ہوں۔ (الشیخان، مؤطا، ابوداؤد)","",{"k":"مسلم (597)۔ ابوداؤد (1504)۔ احمد (8616)۔ مؤطا (488)۔"}],[9303,"سیدنا زید بن ارقم رضی اللہ عنہ سے روایت ہے کہ میں نے نبی کریم صلی اللہ علیہ وسلم کو فرماتے سنا جبکہ سلیمان نے کہا کہ نبی کریم صلی اللہ علیہ وسلم ہر نماز کے بعد کہتے تھے: اے اللہ! اے ہمارے رب اور ہر چیز کے رب میں اس بات کا گواہ ہوں کہ تحقیق تو ہی رب ہے، تو ایک ہے، تیرا کوئی شریک نہیں ہے۔ اے اللہ! اے ہمارے رب اور ہر چیز کے رب! میں گواہ ہوں کہ محمد صلی اللہ علیہ وسلم تیرا بندہ اور تیرا رسول ہے۔ اے اللہ، اے ہمارے رب! اور ہر چیز کے رب! میں گواہ ہوں کہ تمام بندے بھائی بھائی ہیں۔ اے اللہ، اے ہمارے رب اور ہر چیز کے رب! مجھے اور میرے اہل کو اپنے لیے ہر گھڑی دنیا اور آخرت میں مخصوص کر، اے بڑائی اور اکرام کرنے کے مالک! میری دعا سن اور قبول کر۔ اللہ سب سے بڑا ہے، اللہ سب سے بڑا ہے۔ اللہ روشن کرنے والا ہے آسمان اور زمین کو، اللہ بڑا ہے بہت بڑا ہے۔ میرے لیے اللہ کافی ہے اور بہتر اچھا کارساز ہے، اللہ بڑا ہے بہت ہی بڑا ہے۔ (ابوداؤد)","",{"k":"ابوداؤد (1508)۔ ضعیف، البانی: 325۔ احمد (18807)۔"}],[9304,"سیدنا عقبہ بن عامر رضی اللہ عنہ سے مروی ہے کہ وہ کہتے ہیں کہ مجھے رسول کریم صلی اللہ علیہ وسلم نے ہر نماز کے بعد معوذات پڑھنے کا حکم دیا۔ (ابوداود، نسائی)","",{"k":"ابوداؤد (1523)۔ صحیح، البانی: 1348۔ ترمذی (2903)۔ نسائی (5430)۔ احمد (16964)۔"}],[9305,"سیدنا براء بن عازب رضی اللہ عنہ سے مروی ہے، وہ کہتے ہیں کہ جب ہم نبی کریم صلی اللہ علیہ وسلم کے پیچھے نماز پڑھتے تھے تو آپ صلی اللہ علیہ وسلم کے دائیں طرف ہونا پسند کرتے تھے تا کہ آپ ہماری طرف منہ پھیریں، پس میں نے آپ صلی اللہ علیہ وسلم کو کہتے سنا: اے رب! اپنے عذاب سے مجھے بچا جس دن تو بندوں کو اٹھائے گا یا اپنے بندوں کو جمع کرے گا۔ (مسلم)","",{"k":"مسلم (709)، ابوداؤد (615)، نسائی (822)، ابن ماجہ (1006)، احمد (18082)۔"}],[9306,"ابو مروان کا بیان ہے کہ کعب رضی اللہ عنہ نے اس کے سامنے اللہ کی قسم اٹھائی جس نے موسیٰ علیہ السلام کے لیے سمندر کو پھاڑا ہے کہ ہم تورات میں لکھا ہوا پاتے ہیں کہ اللہ کے نبی داؤد علیہ السلام جب نماز سے منہ پھیرتے تھے تو کہتے تھے: اے اللہ! میرے دین کی اصلاح کر جس کو تو نے میرے کام کی عصمت بنایا ہے اور میری دنیا درست کر دے جس میں تو نے میری رہائش رکھی ہے۔ اے اللہ! میں تیرے غصے سے تیری رضا کی پناہ میں آیا اور تیرے عذاب سے تیری معافی کی پناہ میں آیا اور تجھ سے تیری ہی پناہ میں آیا۔ کوئی روکنے والا نہیں ہے جس کو تو دے دے اور کوئی دینے والا نہیں جس چیز کو تو منع کر دے اور فائدہ نہیں دیتی تیرے بالمقابل بڑے کی کوئی بڑائی۔ اور کہا مجھ سے کعب نے بیان کیا کہ صہیب رضی اللہ عنہ نے حدیث بیان کی کہ نبی کریم صلی اللہ علیہ وسلم ان کلمات کو اس وقت کہتے تھے جب آپ نماز سے سلام پھیرتے تھے۔ (نسائی)","",{"k":"نسائی (1346)، ضعیف الاسناد، البانی: 73۔"}],[9307,"سیدنا ابوبکرہ رضی اللہ عنہ سے مروی ہے وہ کہتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم ہر نماز کے بعد یہ کہا کرتے تھے: اے اللہ! میں تیری پناہ مانگتا ہوں کفر سے، فقر سے، اور عذاب قبر سے۔‘‘ (مسلم بن ابی بکرہ کہتے ہیں: میں بھی یہی کلمات کہا کرتا تھا۔ میرے والد نے مجھ سے کہا: بیٹا! تو نے یہ کلمات کس سے سیکھے ہیں؟ میں نے کہا: آپ سے۔ بے شک رسول اللہ صلی اللہ علیہ وسلم ہر نماز کے بعد یہ کلمات پڑھتے تھے۔‘‘","",{"k":"نسائی (1347)، صحیح الاسناد، البانی: 1276، احمد (19896)۔"}],[9308,"سیدنا انس بن مالک رضی اللہ عنہ سے مروی ہے، وہ مرفوع بیان کرتے ہیں: ’’جس نے جمعہ کے دن صبح کی نماز سے پہلے تین بار کہا: میں اس اللہ سے بخش مانگتا ہوں جس کے بغیر کوئی معبود نہیں ہے اور اس کی طرف رجوع کرتا ہوں تو اس کے گناہ بخش دیے جاتے ہیں خواہ وہ سمندر کی جھاگ سے زیادہ ہوں۔‘‘ (الاوسط سند ضعیف)","",{"k":"طبرانی اوسط، وفیہ عبدالعزیز بن عبدالرحمن الباسی وھو ضعیف جدا، ھیثمی: 3019۔","e":"معقبات کہنے کی وجہ یہ ہے کہ یہ کلمات ایک پڑھنے کے بعد پھر پڑھے جاتے ہیں اس لیے انہیں معقبات کہا جاتا ہے یا یہ نمازوں کے بعد پڑھے جاتے ہیں اس وجہ سے کہتے ہیں، ان کے پڑھنے والا ثواب اور جنت سے محروم نہیں ہوتا۔ (جائزۃ الاحوذی: ۴/۳۴۱) سیدنا زید رضی اللہ عنہ والی حدیث سے بظاہر یہ نظر آتا ہے کہ غیر نبی کی خواب پر عمل جائز ہے، حالانکہ ایسا نہیں ہے۔ یہ دراصل نبی صلی اللہ علیہ وسلم کی وحی پر ہی عمل ہے اور دونوں تعداد میں تسبیح کہنا جائز ہے۔ (التعلیقات السلفیہ: ۱/۱۵۸) سبحان اللہ وبحمدہ کی تعداد سو مرتبہ دن میں یا رات میں ایک مجلس میں یا زیادہ مجالس میں پوری کی جاسکتی ہے۔ (جائزۃ الاحوذی: ۴/۳۴۱) مالداروں والی حدیث سے ثابت ہوا کہ یہ اذکار نماز کے بعد مسنون ہیں اور وہ مالدار جو شکر کرنے والا ہے وہ صبر کرنے والے فقیر سے بہتر ہے۔ (عون المعبود: ۱/۵۵۷) تعداد تسبیحات ۳۳، ۱۰۰ دونوں طرح جائز ہے۔ فرض نماز کے بعد آخری دوقل پڑھنا مسنون ہے، ان میں شرک سے بیزاری اور اللہ کی طرف التجا پائی جاتی ہے۔ (عون المعبود: ۱/۵۶۱) سیدنا براء رضی اللہ عنہ والی حدیث سے ثابت ہوتا ہے کہ امام کی دائیں جانب ہونا افضل ہے، اور امام مقتدیوں کی طرف منہ کر لے تا کہ انہیں جس تعلیم کی ضرورت ہے وہ دے سکے اور نصیحت کر سکے اور بعد میں آنے والے کو علم ہو جائے کہ حالت تشہد ختم ہو چکی ہے اور یہ بھی ثابت ہوا کہ نماز کے سلام کے بعد یہ دعا پڑھنا مسنون ہے۔ (عون المعبود: ۱/۲۳۷)"}],[9309,"سیدنا ابو ذر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: میں نے فجر کی نماز کے بعد پاؤں پھیرنے اور کلام کرنے سے پہلے کہا: نہیں کوئی عبادت کے لائق مگر اللہ وہ ایک ہے اس کا کوئی شریک نہیں، اس کی بادشاہت ہے، اسی کی حمد وثنا ہے، وہ زندہ کرتا اور مارتا ہے اور وہ ہر چیز پر قادر ہے، دس بار تو اللہ اس کے لیے دس نیکیاں لکھ دیتا ہے اور دس بدیاں مٹا دیتا ہے اور اس کے دس درجے بلند کر دیتا ہے اور وہ سارا دن ہر مکروہ کام سے اور شیطان کے شر سے محفوظ رہتا ہے اور اس کو کوئی گناہ مقام قرب سے نہیں کرسکتا، اللہ کے ساتھ شرک کرنے سے سوا۔ (ترمذی)","",{"k":"ترمذی (3474)، ضعیف، البانی: 688۔","e":"ترمذی نے اسے حسن، غریب اور صحیح قرار دیا ہے، فجر کی نماز میں حالت تشہد میں پاؤں موڑنے سے پہلے یہ دعا پڑھنا بڑے اجر کا باعث ہے، وجہ یہ ہے کہ جب انسان توحید کے کلمہ سے دعا کرتا ہے تو وہ خود کو حرم میں اور امن میں داخل کر دیتا ہے، کوئی گناہ اللہ کی حرمت کو پامال نہیں کر سکتا، جب توحید کے حرم سے نکل جاتا ہے تو اسے شرک اپنی گرفت میں لے لیتا ہے، یہ شرف وفضل دین میں کمال سے، حرام سے اجتناب اور بڑی بڑی نافرمانیوں سے پاک صاف ہو تو حاصل ہوتا ہے۔ اگر ذکر کثرت سے کرتا رہے اور اپنی شہوات میں مگن رہے اور اللہ کی حرمتوں کی پامالی کرے اور نہ تقویٰ ہو، نہ عمل صالح ہو تو یہ مقدس و مطہر آدمی کے ساتھ شامل نہ ہوگا، نہ اس کے مرتبہ تک پہنچے گا۔ (فتح الباری: ۱۳/۵۳۱)"}],[9310,"سیدہ ام سلمہ رضی اللہ عنہا سے روایت ہے، وہ کہتی ہیں کہ نبی کریم صلی اللہ علیہ وسلم ہر فجر کی نماز کے بعد کہا کرتے تھے: ’’اے اللہ! میں تجھ سے نافع علم، مقبول عمل اور پاکیزہ رزق کا سوال کرتا ہوں۔‘‘ (رزین)","",{"k":"رزین۔"}],[9311,"سیدنا مسلم بن حارث رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے اس سے خفیہ طور پر فرمایا جب تو نماز مغرب سے سلام پھیرے تو کسی سے کلام کرنے سے پہلے سات بار کہا کر۔ اے اللہ! مجھے آگ سے پناہ دے دے۔ اگر تو اس رات فوت ہوا تو تیرے لیے آگ سے پناہ لکھ دی جائے گی۔ اور جب تو فجر کی نماز پڑھے اور یہ کلمات کہہ دے اور پھر اس دن تو فوت ہو جائے تو تیرے لیے آگ سے پناہ لکھ دی جائے گی۔ حارث بن مسلم نے کہا کہ اس دعا کو آپ صلی اللہ علیہ وسلم نے مخفی طور پر بتایا تھا اور ہم اپنے مسلمان بھائیوں کے لیے اس کو عام کرتے ہیں اور ان کو یہ خصوصی ورد بتاتے ہیں۔ (ابوداؤد)","",{"k":"ابوداؤد (5079)، ضعیف، البانی: 1083۔"}],[9312,"سیدنا عمارہ بن شبیب رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس نے نماز مغرب کے بعد دس بار یہ کلمات کہے نہیں: کوئی معبود مگر اللہ جو ایک ہی ہے، اس کا کوئی شریک نہیں ہے، اسی کی بادشاہی ہے اور اس کی حمد وثنا ہے وہ زندہ کرتا اور مارتا ہے اور وہ ہر چیز پر قادر ہے۔ تو اللہ تعالیٰ اسلحہ دے کر پہرے دار اس کے ساتھ لگا دیتا ہے جو فجر تک شیطان سے اس کی حفاظت کرتا ہے اور دس نیکیاں اس کے لیے لکھی جاتی ہیں جو جنت واجب کر دیتی ہیں اور ہلاک کرنے والے دس گناہ اس کے مٹا دیے جاتے ہیں اور دس مومن گردنیں آزاد کرنے کے برابر اجر بھی ملتا ہے۔ (ترمذی)","",{"k":"ترمذی (3534)، حسن، البانی: 2800۔","e":"مغرب کی نماز کے بعد یہ دعا غفلت سے بچاتی ہے اور انسان کو تیاری سے خبر دار رکھتی ہے۔ (جائزۃ الاحوذی: ۴/۵۰۸)"}],[9313,"سیدنا ابوامامہ رضی اللہ عنہ بیان کرتے ہیں: ’’جس نے فرض نمازوں کے بعد آیت الکرسی پڑھی تو اس کے جنت میں داخل ہونے کے لیے موت کے علاوہ کوئی مانع اور رکاوٹ نہیں ہے۔‘‘","",{"k":"طبرانی کبیر: 7532، طبرانی اوسط، باسانید واحدھا جید، ھیثمی: 16922۔"}],[9314,"اور ایک روایت میں ساتھ قُلْ هُوَ اللَّهُ سورت کا بھی ذکر ہے۔","",{"k":"طبرانی کبیر: 7532، والاوسط باسانید واحدھا جید، ھیثمی: 16923۔"}],[9315,"سیدنا حسن بن علی رضی اللہ عنہ نے مرفوع حدیث بیان کی: ’’جس نے ہر فرض نماز کے بعد آیت الکرسی پڑھی تو وہ دوسری نماز تک اللہ کی ذمہ داری پر ہے۔‘‘ (الکبیر)","",{"k":"طبرانی کبیر: 2733، واسنادہ حسن، ھیثمی: 16924۔"}],[9316,"سیدنا انس بن مالک رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم جب سلام پھیرتے تھے تو یہ کلمات کہتے تھے: اے اللہ! میری آخری عمر اچھی کر دے۔ اے اللہ! میرا آخری عمل اپنی رضا کا باعث بنا دے۔ اے اللہ! میرا سب سے بہتر دن وہ کر دے جس میں تجھ سے میری ملاقات ہو۔ (الاوسط سند ضعیف)","",{"k":"طبرانی اوسط وفیہ ابو مالک النخعی وھو ضعیف، ھیثمی: 16974۔","e":"ان احادیث سے ایک تو فرض نماز کے بعد آیت الکرسی کی شان نمایاں ہوتی ہے اور دوسرا یہ بھی ثابت ہوا کہ موت ایک اٹل حقیقت ہے، اس کا کوئی بھی انکار نہیں کر سکتا اور یہ بھی معلوم ہوا کہ جنت پیدا ہو چکی ہے اس کا وجود ہے۔ آیۃ الکرسی اور سورۃ اخلاص کی اتنی فضیلت کی وجہ یہ ہے کہ اس میں توحید الہی کو صاف طور پر نکھار کر بیان کیا گیا ہے۔ اللہ کی وحدانیت، اس کی قدرت اور اس کے علم اور کائنات کی حفاظت وغیرہ صفات کا ذکر اس میں آیا ہے، اس میں کائنات کے رب کی دس صفات ہیں۔ اور سورت اخلاص میں تین بنیادی عقائد ہیں: (۱) توحید (۲) رسالت (۳) آخرت۔ اس میں توحید کوٹ کوٹ کر بھر دی گئی ہے، اس سورت میں اللہ کی وحدانیت اور اس کی صمدیت کا ذکر ہے، یہ سورت بھی اللہ کو بہت ہی محبوب ہے، اسے پڑھنے والے کو قرآن پاک کے تیسرا حصہ پڑھنے کی نوید مسرت سنائی گئی ہے، لہذا جو آدمی ان دونوں کے مطابق عقیدہ وعمل اختیار کر کے فرض نماز کے بعد پڑھنے کا اہتمام کرتا ہے وہ جنت میں داخل ہوگا۔ (تفہیم الاسلام: ۱/ ۳۶۸)"}],[9317,"سیدنا ابن عباس رضی اللہ عنہما سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم جب رات کو نماز تہجد کے لیے اٹھتے تو یوں کہتے: اے اللہ! ہمارے رب! تیری تعریف ہے، تو ہی آسمانوں اور زمینوں اور ان کے اندر رہنے والوں کو قائم رکھنے والا ہے۔ اور تیری تعریف ہے تو آسمانوں اور زمینوں کو اور جو مخلوق ان میں ہے سب کو روشنی دینے والا ہے اور تیرے لیے حمد ہے، تو ہی آسمانوں اور زمینوں کا اور جو ان میں رہنے والے ہیں سب کا مالک ہے۔ اور تیری ہی تعریف ہے تو سچا ہے تیرا وعدہ سچا ہے۔ تیری ملاقات حق ہے جنت حق ہے اور آگ حق ہے، تمام انبیاء علیہم السلام برحق ہیں، محمد صلی اللہ علیہ وسلم حق ہیں اور قیامت حق ہے۔ اے اللہ! میں تیرے لیے تسلیم کرتا، تیرے اوپر ایمان لاتا، تیرے اوپر توکل کرتا ہوں اور تیری طرف رجوع کرتا ہوں۔ تیری مدد کے بل بوتے باطل سے جھگڑتا ہوں اور تیری طرف فیصلہ کرتا ہوں، لہذا تو مجھے بخش دے جو میں نے پہلے کیا اور جو میں نے مؤخر کیا، جو پوشیدہ کیا یا ظاہر کیا اور جو تو میرے سے زیادہ بہتر جانتا ہے، تو ہی پہلے ہے، تو ہی پیچھے ہے، تیرے سوا کوئی معبود نہیں اور نہ تیرے سوا کوئی معبود حقیقی ہو سکتا ہے۔ (چھ نے روایت کی)","",{"k":"بخاری (1120)۔ مسلم (769)۔ ابوداؤد (771)۔ ترمذی (3418)۔ نسائی (1619)۔ ابن ماجہ (1355)۔ دارمی (1486)۔ احمد (3358)۔ موطا (500)۔","e":"یہ دعا نبی کریم صلی اللہ علیہ وسلم تکبیر تحریمہ کے بعد کہا کرتے تھے، یہ بڑی جامع دعا ہے۔ جواہر کا وجود اور اعراض کا وجود، یعنی وہ اشیا جو خود انحصار ہیں اور وہ جو دوسرے کے سہارے ہیں اور چیزوں کو وجود وعدم میں لانا، یہ سب انعامات الہیہ ہیں جو اس نے اپنے بندوں پر نازل کیے ہیں۔ آغاز کا، معاش کا، انتہاء کا، نبوت کا، جزائے کا، ایمان واسلام کا، توکل وانابت کا اور تضرع اور خضوع کا اس میں ذکر کیا گیا ہے اس لیے اس کے شروع میں تمام تعریفات اللہ کے لیے ہی ذکر کی گئی ہیں کہ وہی ان کے لائق ہے۔ اس حدیث سے مزید یہ ثابت ہوا کہ نبی صلی اللہ علیہ وسلم کو اپنے رب کی عظمت و قدرت اور ذکر ودعا اور رب کی ثنا اس کے حقوق کا اعتراف، اس کے وعدہ وعید کی صداقت کی معرفت بھی نمایاں ہے، اس سے یہ بھی ثابت ہوا کہ مطلوب سے پہلے اللہ کی ثنا کی جائے۔ (فتح الباری: ۳/ ۵)"}],[9318,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں جب آپ صلی اللہ علیہ وسلم رات کو اٹھتے اور نماز شروع کرتے تو کہتے تھے: اے اللہ! جبرائیل، میکائیل اور اسرافیل کے رب، آسمانوں اور زمین کو پیدا کرنے والے، غیب اور ظاہر کو جاننے والے (تو اپنے بندوں کے درمیان فیصلہ کرے گا) تا آخر آیت۔ اے اللہ! مجھے ہدایت دے اپنے حکم کے ساتھ، ہر اس چیز میں جو حق کے بارے میں اختلاف کیا گیا ہے۔ (مسلم اور اصحاب سنن)","",{"k":"مسلم (770)۔ ابوداؤد (767)۔ ترمذی (3420)۔ نسائی (1625)۔ ابن ماجہ (1356)۔ احمد (24699)۔","e":"یہ دعا بھی تکبیر تحریمہ کے بعد پڑھنی مسنون ہے، جبریل، میکائیل اور اسرافیل کو ان کی تشریف آوری اور برتری کی وجہ سے مقدم کیا گیا ہے، جبریل علیہ السلام آسمانی کتابوں کے امین ہیں، تمام دینی امور کا یہ منبع ہیں، اور اسرافیل لوح محفوظ کے امین ہیں۔ یہ صور پھونکیں گے اور معاش و معاد کا ہر معاملہ ان کے سپرد ہے اور میکائیل بارش، نباتات اور دین ودنیا اور آخرت کے امور کے نگران ہیں۔ اور اللہ تعالیٰ روز قیامت حق والے اور باطل والے کے درمیان، ثواب والے اور عذاب والے کے درمیان فیصلہ کرے گا، دین یا دنیا کے ہر معاملہ کا فیصلہ کرے گا، اس لیے فرمایا: سیدھی راہ تیری توفیق سے ہی میسر آتی ہے۔ (عون المعبود: ۱/ ۲۷۹)"}],[9319,"شریق ھوزنی سے منقول ہے، اس نے کہا کہ میں سیدہ عائشہ رضی اللہ عنہا کے پاس آیا تو میں نے اس سے سوال کیا کہ نبی صلی اللہ علیہ وسلم جب رات کو اٹھتے تھے تو کس چیز کے ساتھ نماز شروع کرتے تھے تو انہوں نے کہا: تو نے مجھ سے اس چیز کے بارے میں سوال کیا ہے جس کے متعلق تجھ سے پہلے کسی نے سوال نہیں کیا۔ جب آپ صلی اللہ علیہ وسلم رات کو اٹھتے تو دس بار تکبیر کہتے، دس بار تحمید کہتے اور سبحان اللہ وبحمدہ دس بار کہتے اور سبحان الملک القدوس دس بار کہتے اور دس بار استغفار کرتے اور دس بار تہلیل کرتے پھر کہتے: اے اللہ! میں دنیا اور قیامت کے دن کی تنگی سے تیری پناہ مانگتا ہوں، پھر نماز شروع کرتے تھے۔ (ابوداؤد)","",{"k":"ابوداؤد (5085)۔ حسن صحیح، البانی: 4242۔"}],[9320,"عاصم بن حمید سے روایت ہے کہ اس نے عائشہ رضی اللہ عنہا سے سوال کیا کہ نبی کریم صلی اللہ علیہ وسلم رات کے قیام کو کس چیز کے ساتھ شروع کرتے تھے؟ تو انہوں نے کہا تو نے مجھ سے وہ چیز پوچھی ہے جو تیرے سے پہلے کسی نے نہیں پوچھی جب آپ صلی اللہ علیہ وسلم اٹھتے دس بار تکبیر کہتے، دس بار الحمد للہ کہتے، دس بار سبحان اللہ کہتے، دس بار لا الہ الا اللہ کہتے دس بار استغفار کرتے اور کہتے تھے: اے اللہ! مجھے بخش دے، مجھے ہدایت دے، مجھے رزق دے، مجھے معافی دے اور قیامت کے دن کی تنگی کے مقام سے اللہ کی پناہ مانگتے تھے۔","",{"k":"نسائی (1617)۔ حسن صحیح، البانی: 1525۔ ابوداؤد (766)۔ احمد (24578)۔","e":"اس میں عمدہ سوال کرنے پر تحسین کرنے کا ثبوت ہے اور لوگوں کی غفلت پر اظہار تاسف ہے، دارین کی امراض اور ظاہر وباطنی بلاؤں سے عافیت طلب کی گئی ہے اور روز قیامت کی سختیوں اور ہولناکیوں سے اللہ کی پناہ طلب کی گئی ہے۔ (عون المعبود: ۱/ ۲۷۹)"}],[9321,"سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت ہے، وہ کہتے ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم رات کو کھڑے ہوتے تو تکبیر کہتے تھے، پھر کہتے: پاک ہے تو اے اللہ! تیری حمد وثنا ہے، تیرا نام برکت والا ہے، تیری ذات بلند ہے اور تیرے سوا کوئی معبود نہیں ہے۔ اللہ بڑا ہے بہت بڑا ہے، پھر کہتے تھے: میں اللہ تعالیٰ سننے جاننے والے کی پناہ مانگتا ہوں شیطان مردود سے، اس کے طعن مارنے سے، اس کے سانس اور اس کے تکبر سے۔ (اصحاب سنن)","",{"k":"ترمذی (242)۔ صحیح، البانی: 201۔ ابوداؤد (775)۔ نسائی (900)۔ ابن ماجہ (804)۔ دارمی (1239)۔ احمد (11081)۔","e":"اس میں منفی صفات کو دور کیا گیا ہے اور مثبت صفات کو ثابت کیا گیا ہے اور اللہ کے اسم گرامی کی برکات بیان ہوئی ہیں، دوسروں کی عظمت و رفعت پر اللہ کی بلندی کا اظہار ہے اور شیطان کے وسوسوں سے پناہ طلب کی گئی ہے۔ (عون المعبود: ۱/ ۸۱)"}],[9322,"سیدنا انس بن مالک رضی اللہ عنہ سے مروی ہے، وہ کہتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم ایک اعرابی کے پاس سے گزرے، وہ اپنی نماز میں یوں دعا مانگتا تھا: اے وہ ذات جس کو آنکھیں نہیں دیکھتیں اور گمان اس پر پھنس جاتا ہے اور جس کا وصف بیان کرنے سے بیان کرنے والے عاجز ہیں اور جس پر حادثات کا کوئی اثر نہیں پڑتا اور وہ جو زمانے کے چکر سے نہیں ڈرتا، وہ پہاڑوں کا بوجھ جانتا ہے اور سمندر کا پیمانہ اس کے علم میں ہے، بارش کے قطروں کی تعداد، درختوں کے پتوں کی تعداد، اور ہر اس چیز کی تعداد جو رات کی تاریکی میں ہے اور وہ چیز جس پر دن روشن ہوتا ہے اور نہیں چھپا سکتے اس سے آسمان دوسرے آسمان کو اور نہ زمین دوسری زمین کو چھپا سکتی ہے اور اس سے سمندر نہیں چھپا سکتا جو اس کی گہرائی میں ہے اور نہ پہاڑ چھپا سکتا ہے جو اس کے اندرونی حصے میں ہے میرے لیے بہتر آخری عمر کر دے اور میرا آخری عمل بہتر کر دے اور میرا خوشی کا دن سب سے بہتر کر دے جس سے میں تیری ملاقات کروں۔ پس نبی کریم صلی اللہ علیہ وسلم نے ایک شخص اعرابی کے ساتھ لگا دیا کہ جب یہ نماز سے فارغ ہو تو اس کو میرے پاس لائے۔ چنانچہ جب وہ آپ صلی اللہ علیہ وسلم کے پاس آیا تو اس وقت کسی کان سے آپ صلی اللہ علیہ وسلم کے پاس بطور تحفہ سونا پیش کیا گیا تھا۔ جب اعرابی آپ صلی اللہ علیہ وسلم کے پاس آیا تو وہ سونا اس کو بخش دیا اور فرمایا: اے اعرابی! تو کس قوم سے ہے؟ اس نے کہا: میں بنو عامر بن صعصعہ سے ہوں اور فرمایا: تجھے معلوم ہوا کہ میں نے تجھے سونا کیوں دیا ہے؟ اس نے کہا: ہمارے اور آپ صلی اللہ علیہ وسلم کے درمیان قرابتداری ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: قرابتداری پر صلہ رحمی کرنے کا حق ہے لیکن میں نے تجھے سونا اس لیے دیا ہے کہ تو نے اللہ تعالیٰ کی بہت اچھے طریقے سے ثنا بیان کی ہے۔ (الاوسط)","",{"k":"الاوسط، ہیثمی: 17267۔ رواہ الطبرانی فی الاوسط، ورجالہ رجال الصحیح غیر عبداللہ بن محمد بن ابی عبدالرحمن الاذرمی، وہو ثقۃ۔"}],[9323,"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ سیدنا ابوبکر رضی اللہ عنہ نے عرض کی: یارسول اللہ! مجھے کچھ کلمات کہنے کا حکم دیجیے تا کہ میں صبح وشام وہ کلمات کہا کروں۔ آپ نے فرمایا: یہ کہا کرو: اے اللہ! آسمانوں اور زمین کو پیدا کرنے والے، غیب اور ظاہر کو جاننے والے، ہر چیز کے رب اور مالک۔ میں گواہی دیتا ہوں کہ تیرے علاوہ کوئی معبود نہیں ہے۔ میں اپنے نفس کے شر سے تیری پناہ طلب کرتا ہوں اور شیطان کے شر اور اس کی شراکت سے۔ آپ نے فرمایا: یہ کلمات صبح و شام اور بستر پر لیٹتے وقت پڑھا کر۔","",{"k":"ترمذی (3392)۔","e":"اس میں نفس اور شیطان کے شرک وشر سے پناہ مانگی گئی ہے اور شیطان نے جو جال بچھا رکھا ہے اور جس کے ذریعے سے وہ لوگوں کو فتنے میں ڈالتا ہے اس سے اللہ کی پناہ ڈھونڈی گئی ہے۔ (جائزۃ الاحوذی: ۴/ ۴۳۱)"}],[9324,"سیدنا ابو عیاش رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس نے صبح کو کہا نہیں کوئی معبود مگر اللہ، وہ ایک ہے، اس کا کوئی شریک نہیں ہے، اُسی کے لیے بادشاہی ہے اور سب تعریف اسی کے لیے ہے اور وہ ہر چیز پر قادر ہے تو اس کے لیے اولاد اسماعیل سے ایک غلام آزاد کرنے کے برابر اجر ہوگا، اس کے لیے دس نیکیاں لکھی جائیں گی، دس گناہ مٹائے جائیں گے، دس درجے بلند کیے جائیں گے، رات تک شیطان کے شر سے محفوظ ہوگا اور اگر یہ کلمات رات کو کہے گا تو صبح تک اس کے مثل اجر ہوگا۔ حماد کہتے ہیں: ایک آدمی نے خواب میں رسول اللہ صلی اللہ علیہ وسلم کو دیکھا اور آپ سے عرض کی کہ ابو عیاش آپ صلی اللہ علیہ وسلم کی طرف سے اس طرح بیان کرتا ہے، آپ نے فرمایا: ’’ابو عیاش صحیح کہتا ہے۔‘‘ (ابوداود)","",{"e":"اس دعا میں ہر طاغوت کا انکار ہے اور اللہ تعالیٰ پر ایمان کا اقرار ہے۔ حضرت اسماعیل علیہ السلام چونکہ نامور خاندان سے ہیں، جس قدر خاندانی شرف ہوگا اسی قدر اس گردن کی آزادی باعث اجر ہوگی۔ (تفہیم الاسلام: ۲/ ۹۶۸)"}],[9325,"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس نے صبح یا شام کہا: اے اللہ! میں صبح کے وقت تجھے گواہ بناتا ہوں اور تیرے عرش کے حاملین کو اور تیرے سب فرشتوں اور تیری ساری مخلوق کو گواہ بناتا ہوں، تو ہی اللہ ہے، تیرے سوا کوئی معبود نہیں ہے اور محمد صلی اللہ علیہ وسلم تیرے بندہ اور تیرے رسول ہیں تو اللہ تعالیٰ اس کا چوتھائی حصہ جہنم سے آزاد کر دیتا ہے اور جس نے دو بار کہا، اللہ اس کا نصف حصہ آزاد کر دیتا ہے اور جس نے تین بار کہا اور تین چوتھائی آزاد کر دیتا ہے اور جس نے چار بار کہا اللہ تعالیٰ اس کو آزاد کر دیتا ہے۔‘‘ (ترمذی اور ابوداود کے الفاظ ہیں)","",{"k":"ابوداؤد (5069)۔ ضعیف، البانی: 1077۔"}],[9326,"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم اپنے اصحاب کو تعلیم دیتے اور فرماتے: تم میں سے ہر ایک صبح کو اس طرح کہے: اے اللہ! ہم نے تیرے ساتھ صبح کی، تیرے ساتھ زندہ رہیں گے اور تیرے ساتھ مریں گے اور تیری طرف پھر کر جانا ہوگا۔ (ابوداؤد، ترمذی کے الفاظ ہیں)","",{"k":"ترمذی (3391)۔ صحیح، البانی: 2700۔ ابن ماجہ (3868)۔"}],[9327,"سیدنا ابن مسعود رضی اللہ عنہ سے روایت ہے، وہ کہتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم شام کے وقت کہتے تھے: ہم نے شام کی اور شام کی بادشاہی نے اللہ کے لیے ہے اور سب تعریف اللہ کے لیے ہے۔ اللہ کے سوا کوئی معبود نہیں ہے، وہ ایک ہے، اس کا کوئی شریک نہیں ہے، اسی کے لیے بادشاہی ہے اور اسی کی حمد وثنا ہے اور وہ ہر چیز پر قادر ہے اور میں اس رات کے شر سے اور اس کے بعد کے شر سے تیری پناہ مانگتا ہوں۔ اے اللہ! میں سستی سے اور بڑے بڑھاپے سے تیری پناہ مانگتا ہوں۔ اے اللہ! میں تیری پناہ مانگتا ہوں آگ کے اور قبر کے عذاب سے اور صبح کے وقت اسی طرح کہے ہم نے صبح کی اور سب ملک اللہ ہی کا ہے۔ (مسلم، ترمذی، ابوداؤد)","",{"k":"مسلم (2723)۔ ترمذی (3390)۔ ابوداؤد (5071)۔ احمد (4181)۔"}],[9328,"بنو ہاشم کے غلام عبدالحمید سے منقول ہے کہ اس کی ماں نے اس کو بیان کیا کہ وہ نبی کریم صلی اللہ علیہ وسلم کی بیٹیوں کی خدمت کرتی تھی۔ نبی صلی اللہ علیہ وسلم نے اپنی ایک بیٹی کو فرمایا: تو صبح کو کہا کر: پاک ہے اللہ اور اس کی حمد وثنا ہے۔ نیکی حاصل کرنے کی توفیق نہیں ہے مگر اللہ کے ساتھ، جو اللہ چاہے وہ ہوگا اور جو کچھ وہ نہ چاہے نہیں ہوگا۔ میں جانتی ہوں کہ اللہ ہر چیز پر قادر ہے اور اللہ تعالیٰ نے ہر چیز کو اپنے علم میں سما لیا ہے۔ جس نے صبح کو یہ کہا وہ شام تک حفاظت میں رہے گا اور جس نے شام کو یہ کہا وہ صبح تک حفاظت میں رہے گا۔","",{"k":"ابوداؤد (5075)۔ ضعیف، البانی: 1080۔"}],[9329,"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس نے صبح شام کہا: ہم راضی ہیں اللہ کو رب مان کر اسلام کو دین مان کر، اور محمد صلی اللہ علیہ وسلم کو رسول مان کر تو اللہ پر حق ہے کہ اس کو راضی کر دے۔‘‘","",{"k":"ابوداؤد (5072)۔ ضعیف، البانی: 1078۔ ابن ماجہ (3870)۔ احمد (18488)۔","e":"یعنی ہم رات میں داخل ہوئے اور ملک بھی اللہ ہی کا ہے اور ہمیشہ کے لیے ہے اور معبود صرف وہی ہے، اطاعت کے کاموں میں اور امور خیر کی سرانجامی میں جو سستی ہو سکتی ہے اس سے اللہ کی پناہ لی ہے اور خود کو لوگوں سے برتر سمجھنا، اور تکبر سے اللہ کی پناہ مانگی گئی ہے۔"}],[9330,"سیدنا بریدہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: جس نے صبح و شام کہا: اے اللہ! تو میرا رب ہے، تیرے سوا کوئی معبود نہیں ہے، تو نے مجھے پیدا کیا ہے، میں تیرا بندہ ہوں اور تیرے معاہدے اور تیرے وعدے پر ہوں جہاں تک میری طاقت ہے میں تیری پناہ مانگتا ہوں، اس عمل کے شر سے جو میں نے کیا ہے، میں تیری نعمتوں کا اقرار کرتا ہوں اور اپنے گناہوں کا اعتراف کرتا ہوں، پس تو مجھے بخش دے۔ یقیناً تیرے سوا گناہوں کو کوئی نہیں بخشتا۔ پس اگر وہ اس رات یا دن فوت ہوا تو وہ جنت میں داخل ہوگا۔‘‘","",{"k":"ابوداؤد (5070)۔ صحیح، البانی: 4237۔ ابن ماجہ (3872)۔ احمد (22504)۔"}],[9331,"سیدنا عبداللہ بن غنام البیاضی رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس نے صبح کے وقت کہا: اے اللہ! صبح کے وقت میرے اوپر جو نعمت ہے وہ تیری طرف سے ہے، تو اکیلا ہے، تیرا کوئی شریک نہیں، تیری حمد ہے اور تیرا شکر ہے تو اس نے اس دن کا شکر ادا کر دیا۔ اور جس نے اس کے مثل شام کو کہا تو اس نے اس رات کا شکر ادا کر دیا۔","",{"k":"ابوداؤد (5073)۔ ضعیف، البانی: 1079۔","e":"اس میں اللہ تعالیٰ کی وحدانیت، اس کی عبادت، خالق ہونے کا اعتراف، اس سے عہد و وعدہ کا اقرار اور گناہ سے اس کی پناہ، انعامات کا اسے موجد، اور اسے ہی قادر مطلق تسلیم کیا گیا ہے، یہ ایسے جامع اسباب ہیں جو اس میں بیان ہوئے ہیں جو کسی اور جگہ نہیں اس لیے یہ استغفار کی رئیس دعا ہے، اس دعا میں عظمت و جلالت الہی کا جو حق ہے اس کا اعتراف ہے اور بندے کو اس مالک کل کے سامنے جس بندگی کی ضرورت ہے، ذلت اور خضوع اور انکساری کا اظہار کرنا چاہیے وہ ہوا ہے، اس میں اعتراف ہے کہ وہی خالق و رازق ہے، وہی عطا کرنے والا ہے اور چھین لینے والا ہے، وہی زندہ کرنے والا اور مارنے والا ہے، وہی تمام امور کا مدبر اعلیٰ ہے۔ شرارتیں یا تو غیر سے ہوتی ہیں یا خود اپنے گناہوں سے ہوتی ہیں، ان دونوں شرارتوں سے اپنے پروردگار کے ہاں پختہ توبہ چاہتے ہوئے ان سے اپنا دفاع کرتا ہے۔ اور پھر آدمی اعتراف کرتا ہے اس منعم حقیقی کی نعمتوں کا کہ جس اکیلے نے ہی انعامات کی ہر طرف برکھا بہا دی ہے، جس طرح مولیٰ تیرے انعامات بے حد وشمار ہیں، اسی طرح حمد وشکر بھی بے حد وشمار فقط تیری ذات بے ہمتا کے ہی لائق ہے۔ (تفہیم الاسلام: ۲/ ۹۸۵)"}],[9332,"سیدنا ابن عمر رضی اللہ عنہ روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم صبح و شام یہ کلمات کہنا ترک نہیں کرتے تھے۔ اے اللہ! میں تجھ سے دنیا اور آخرت میں عافیت طلب کرتا ہوں۔ اے اللہ! میں تجھ سے معاف کرنے اور عافیت عطا کرنے کا سوال کرتا ہوں کہ میرے دین میں، میری دنیا میں، میرے اہل اور میرے مال میں عفو و عافیت عنایت فرما۔ اے اللہ! میری پردہ پوشی کر اور میرے خوف سے مجھے امن دے دے۔ اے اللہ! میری حفاظت کر آگے سے میرے پیچھے، میرے دائیں، میرے بائیں، میرے اوپر سے اور میں تیری عظمت کی پناہ میں آتا ہوں اس سے کہ میں نیچے سے اچانک پکڑا جاؤں۔‘‘","",{"k":"ابوداؤد (5074)۔ صحیح، البانی: 4239۔ نسائی (5529)۔ ابن ماجہ (3871)۔ احمد (4770)۔"}],[9333,"سیدنا ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس نے صبح کے وقت یہ آیت تلاوت کی: ’’پاکیزگی سب اللہ کے لیے جس وقت تم صبح وشام کرتے ہو اور اسی کے لیے حمد وثنا ہے آسمانوں اور زمینوں.... تو اس نے اس دن کے ورد کا اجر پالیا اور جس نے یہ آیت شام کو تلاوت کی اس نے رات کا فوت شدہ حزب کا اجر حاصل کیا۔‘‘","",{"k":"ابوداؤد (5076)۔ ضعیف جدا، البانی: 1081۔"}],[9334,"سیدنا ابو مالک رضی اللہ عنہ سے مروی ہے، وہ کہتے ہیں کہ لوگوں نے عرض کی: یارسول اللہ! ہمیں چند کلمات تعلیم کر دیجیے تا کہ ہم صبح وشام اور لیٹتے وقت بستر پر کہیں۔ پس آپ نے حکم دیا کہ وہ کہیں: اے اللہ! آسمانوں کو اور زمین کو پیدا کرنے والے، غیب اور ظاہر کو جاننے والے! تو ہی ہر چیز کا رب ہے اور فرشتے بھی یہ گواہی دیتے ہیں کہ صرف تو ہی معبود ہے۔ ہم اپنے نفس کے شر سے تیری پناہ طلب کرتے ہیں اور تیری پناہ طلب کرتے ہیں شیطان مردود کے شر سے اور اس کی شراکت سے اور اس بات سے تیری پناہ طلب کرتے ہیں کہ ہم کوئی جرم کریں یا کسی مسلمان پر زیادتی اور شر پہنچائیں۔ (ابوداود)‘‘","",{"k":"ابوداؤد (5083)۔ ضعیف، البانی: 1086۔"}],[9335,"امام ابو داود نے اسی سند کے ساتھ کہا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: تم میں سے ہر ایک صبح کو کہا کرے: ہم صبح کو پہنچے اور سارا ملک اللہ تعالیٰ رب العالمین کے لیے۔ اے اللہ! میں تجھ سے اس دن کی خیر، فتح، نصرت، نور، برکت اور ہدایت کا سوال کرتا ہوں۔ میں اس کے شر سے اور اس دن کے بعد کے شر سے تیری پناہ طلب کرتا ہوں۔ پھر رات آئے تو اسی طرح دعا طلب کرے۔","",{"k":"ابوداؤد (5084)۔ ضعیف، البانی: 1088۔"}],[9336,"قاسم سے مروی ہے کہ سیدنا ابوذر رضی اللہ عنہ نے فرمایا: جس نے صبح کو کہا: اے اللہ! جو میں نے قسم کشائی کی یا جو میں نے نذر مانی یا جو میں نے کہا ہے پس تیری مشیت تیرے سامنے ہے اور جو تو چاہے وہ ہو جاتا ہے اور جو تو نہ چاہے وہ نہیں ہوتا ہے۔ اے اللہ! یہ تمام امور مجھے بخش دے اور ان سے درگزر کر دے۔ اے اللہ! میں نے جس پر دعا کی، وہ اس پر ہو اور جس پر میں نے لعنت کی تو لعنت اسی پر ہو۔ تو یہ سارے دن میں ان شاء اللہ کہنا شمار ہوگا۔ (یہ ابوداود کی روایات ہیں)","",{"k":"ابوداؤد (5087)۔ ضعیف الاسناد موقوف، البانی: 1088۔","e":"یہ کلمات آفات، شرور وفتن اور مصائب و مشکلات کے لیے بہت محفوظ قلعہ ہیں، اس لیے نبی کریم صلی اللہ علیہ وسلم انہیں صبح وشام پڑھتے تھے، ہمیں بھی انہیں وردِ زبان بنانا چاہیے۔ ان میں اللہ تعالیٰ سے عافیت کا سوال ہے کہ دین میں عافیت رہے، بدعت نہ اپناؤں، نافرمانیاں نہ کروں اور دین کے واجبات میں سستی نہ کروں، دنیا کی عافیت یہ ہے کہ اس کی شرارتوں، فتنوں اور مصائب و مشکلات سے بچوں اور اس کے دھوکے میں نہ آؤں، اس میں اتنا زیادہ مشغول نہ ہو جاؤں کہ آخرت سے غافل ہو جاؤں، گھر والوں میں عافیت یہ ہے کہ ان کا دین محفوظ رہے، یہ شہوات اور شہادت کا شکار نہ ہو جائیں اور جسمانی بیماریوں سے سلامت رہیں، دنیا کے فتنوں سے ان کے دل سلامت ہوں۔ پردہ پوشی کا سوال یہ ہے کہ برے اعمال لوگوں کی نظروں سے چھپے رہیں، اور توبہ کی توفیق مل جائے۔ دنیا و آخرت کی رسوائی سے سلامتی رہے اور رزق ولباس مل جائے، کہیں عزت و بدن دونوں نہ کھو بیٹھوں، خوف سے امن کا مطلب ہے دنیا کی مصیبتوں اور خوفناک حادثوں اور قیامت کے ہولناک حالات سے امن رہے، چھ اطراف سے، سامنے، دائیں بائیں، اوپر نیچے سے کامل تحفظ کی التجا ہے کہ نفس کے دشمن، انسانوں میں سے دشمن اور شیطانوں میں سے دشمن ہر ایک سے میری حفاظت فرمانا اور قارون اور فرعون جس طرح اچانک اچک لیے گئے مجھے ایسی آفتوں سے محفوظ فرمانا۔ (تفہیم الاسلام: ۲/ ۹۸۶)"}],[9337,"سیدنا عثمان بن عفان رضی اللہ عنہ روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جو بندہ روزانہ صبح وشام یہ کلمات کہے کہ اس اللہ کے نام سے جس کے نام کے ساتھ کوئی چیز آسمان میں اور زمین میں ضرر نہیں پہنچا سکتی ہے اور وہ خوب سننے والا اور سب کچھ جاننے والا ہے۔ اسے کوئی آفت نہیں پہنچے گی اور جس نے شام کو کہا تو اس رات اس کو کوئی ناگہانی بلا نہیں پہنچے گی۔ پھر ابن عثمان ابان کو فالج ہوا اور اس آدمی نے دیکھا جس کو ابان نے یہ حدیث بتائی تھی تو وہ ابان کو تعجب سے دیکھنے لگا۔ ابان نے کہا: تو میری طرف تعجب سے دیکھتا ہے تو سن: اللہ کی قسم! میں نے اپنے باپ عثمان پر جھوٹ نہیں کہا اور عثمان رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم پر جھوٹ نہیں کہا مگر جس دن مجھے یہ بیماری لاحق ہوئی ہے اس دن میں یہ دعا کرنا بھول گیا اور میں نے یہ کلمات نہیں کہے تھے تاکہ اللہ کی تقدیر نافذ ہو کر پوری ہو جائے۔","",{"k":"ترمذی (3388)۔ حسن صحیح، البانی: 2698۔ ابن ماجہ (3869)۔","e":"یعنی فجر کے آغاز پر اور رات کے وقت یعنی نماز فجر اور نماز مغرب کے بعد یہ دعا پڑھنے سے فالج نہ ہوگا، ثابت ہوا کہ یہ دعا پڑھنا اور نقصان کا ہونا دونوں یکجا نہیں ہو سکتے، یہ پڑھنے سے نقصان سے حفاظت رہتی ہے، اگر اللہ کا فیصلہ ہو چکا ہو نقصان مقدر ہو چکا ہو تو اس میں کوتاہی ہو جاتی ہے۔ (جائزۃ الاحوذی: ۴/ ۴۲۹)"}],[9338,"معاذ بن عبداللہ بن حبیب سے مروی ہے کہ وہ اپنے باپ سے بیان کرتے ہیں کہ ہم بارش والی اور سخت تاریکی والی رات میں نکلے کہ ہم رسول اللہ صلی اللہ علیہ وسلم کو تلاش کریں تاکہ آپ صلی اللہ علیہ وسلم ہمیں نماز پڑھا دیں اس نے کہا میں نے آپ صلی اللہ علیہ وسلم کو پایا، آپ نے فرمایا: تو کہہ پس میں نے کچھ نہ کہا، پھر آپ صلی اللہ علیہ وسلم نے فرمایا تو کہہ میں نے کچھ نہ کہا پھر میں نے کہا: کیا کہوں؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا: صبح اور شام آخری تین سورتیں اخلاص، الفلق، الناس، پڑھا کر، یہ تجھے ہر چیز سے کفایت کر جائیں گی۔","",{"k":"ترمذی (3575)۔ حسن، البانی: 2829۔ ابوداؤد (5082)۔ نسائی (5428)۔","e":"اس سے ہر برائی کا دفاع ہو جاتا ہے اور ہر اچھائی کے لیے یہ کافی ہے۔ (جائزۃ الاحوذی: ۴/ ۵۲۸)"}],[9339,"سیدنا ابوہریرہ رضی اللہ عنہ مرفوع بیان کرتے ہیں جس نے صبح اور شام کے وقت سو مرتبہ کہا: پاک ہے اللہ اس کی حمد وثنا کے ساتھ، قیامت کے دن کوئی شخص اس جیسا افضل عمل نہیں لائے گا، سوائے اس شخص کے جس نے اس سے زیادہ مرتبہ یہ کلمات کہے۔","",{"k":"ترمذی (3469)۔ صحیح، البانی: 2762۔ بخاری (6405)۔ مسلم (2692)۔ ابوداؤد (5091)۔ ابن ماجہ (3806)۔ احمد (8656)۔ موطا (486)۔"}],[9340,"سیدہ ام سلمہ رضی اللہ عنہا سے مروی ہے، وہ کہتی ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے مجھے یہ کلمات شام کے وقت کہنے کے لیے تعلیم فرمائے۔ اے اللہ! یہ تیری رات آنے کا وقت ہے اور تیرے دن کے جانے کا وقت ہے اور تیری نداء کی آواز ہیں اور تیری نماز کا وقت ہے، میں تجھ سے سوال کرتی ہوں کہ مجھے بخش دے۔","",{"k":"ترمذی (3579)۔ ضعیف، البانی: 724۔ ابوداؤد (530)۔"}],[9341,"عبدالرحمن بن ابزی اپنے باپ سے روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم صبح کے وقت کہتے تھے: ہم نے صبح کی فطرت اسلام اور کلمہ اخلاص پر۔ اور اپنے نبی محمد صلی اللہ علیہ وسلم کے دین پر اور ملت ابراہیم پر جو یک طرف تھے اور مسلمان تھے اور وہ شرک کرنے والوں سے نہ تھے۔ (رزین)","",{"k":"رزین۔"}],[9342,"سیدنا زید بن ثابت رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے اس کو یہ دعا تعلیم فرمائی ہے اور اس کو حکم دیا کہ وہ اور اس کے گھر کے افراد ہر روز یہ کلمات صبح کے وقت کہا کریں۔ اے اللہ! میں حاضر ہوں اے اللہ! میں حاضر ہوں۔ سعادت تیری طرف سے ہے اور ہر بھلائی تیرے ہاتھ میں ہے تیری طرف سے، تیرے ساتھ اور تیری طرف، اے اللہ! میں نے جو کچھ کہا اور جو نذر مانی اور جو قسم کھائی تو اس سے پہلے تیری مشیت اور تیرا چاہنا موجود ہے۔ تو جو چاہے وہ ہوتا ہے اور جو تو نہ چاہے وہ نہیں ہوتا۔ نہ بدی سے بچنے کی توفیق اور نہ نیکی حاصل کرنے کی توفیق ہے مگر تیرے ساتھ، بے شک تو ہر چیز پر قادر ہے، اے اللہ! جس پر میں دعا کرتا ہوں وہ اس پر ہو اور جس پر میں لعنت کرتا ہوں وہ اس پر ہو، تو ہی میرا کارساز دنیا میں اور آخرت میں، مجھے مسلمان کر کے مار اور مجھے نیک بندوں کے ساتھ ملا دے۔ اے اللہ! میں تیری تقدیر پر راضی رہنے کی توفیق مانگتا ہوں اور مرنے کے بعد ٹھنڈی زندگی چاہتا ہوں اور تیرے چہرے کی طرف لذت کے ساتھ دیکھنے کی توفیق چاہتا ہوں اور تیری ملاقات کا شوق چاہتا ہوں، جس میں نہ ضرر ہو اور نہ مضر ہو اور نہ گمراہ کرنے والا فتنہ ہو، میں تیری پناہ چاہتا ہوں کہ میں ظلم کروں یا میرے اوپر ظلم ہو اور یا میں زیادتی کروں یا میرے اوپر زیادتی کی جائے یا میں اعمال ضائع کرنے والی بدی کروں یا ایسا گناہ کروں جو بخشا نہ جائے۔ اے اللہ! آسمان وزمین کو پیدا کرنے والے، غیب اور ظاہر کو جاننے والے، بڑائی اور سخاوت والے! میں اس دنیاوی زندگی میں تیرے ساتھ وعدہ کرتا اور تجھے گواہ بناتا ہوں اور تو کافی گواہ ہے۔ بے شک میں گواہی دیتا ہوں کہ تیرے سوا کوئی معبود نہیں ہے، تیرا کوئی شریک نہیں ہے، تیرے لیے بادشاہی ہے اور تیرے لیے حمد وثنا ہے اور تو ہر چیز پر قادر ہے اور میں گواہی دیتا ہوں کہ محمد صلی اللہ علیہ وسلم تیرا بندہ اور تیرا رسول ہے۔ اور میں گواہی دیتا ہوں کہ تیرا وعدہ حق ہے اور تیری ملاقات میں کوئی شک نہیں ہے اور تو ان لوگوں کو اٹھانے والا ہے جو قبروں میں ہیں اور میں گواہی دیتا ہوں کہ اگر تو نے مجھے میرے نفس کے حوالے کر دیا تو ضائع ہونے، بے پروا ہونے اور گناہ کرنے اور خطاء کے حوالے کر دیا جاؤں گا۔ اور میں تیری رحمت کے سوا کسی چیز پر اعتماد نہیں کرتا۔ پس تو میرے سب گناہ بخش دے۔ بے شک گناہوں کو نہیں بخشتا مگر تو اور میرے اوپر رجوع فرما، تو توبہ قبول کرنے والا مہربان ہے۔ (احمد اور الکبیر)","",{"k":"احمد (21158)۔ طبرانی کبیر واحد اسنادی الطبرانی رجالہ وثقوا وفی بقیۃ الاسانید ابوبکر بن ابی مریم وہو ضعیف، ہیثمی: 16988۔"}]])